/* olismo-export.js — Export universale risposte motori AI (PDF via stampa, Word via .doc)
   (c) 2026 Avv. Carlo Alberto Calcagno - olismo-integrato.it */
(function () {
  "use strict";
  if (window.__olismoExportLoaded) return;
  window.__olismoExportLoaded = true;

  var CONTAINER_IDS = ["cmResultBody","empResultBody","aiResultBody","chatMessages",
    "chat-messages","chatArea","fes-chat","bush-chat","diet-chat-msgs","diet-result"];
  var BUBBLE_SEL = ".msg-bubble, .sp-msg-bubble, .bubble, .message-bubble";
  var WRAP_SEL = ".msg, .sp-msg, .message, .chat-msg";

  function isVisible(el) {
    if (!el) return false;
    if (el.offsetParent !== null) return true;
    var st = window.getComputedStyle(el);
    return !!st && st.display !== "none" && st.visibility !== "hidden";
  }

  function findContainer() {
    for (var i = 0; i < CONTAINER_IDS.length; i++) {
      var el = document.getElementById(CONTAINER_IDS[i]);
      if (el && isVisible(el) && (el.textContent || "").trim().length > 0) return el;
    }
    return null;
  }

  function clean(node) {
    var c = node.cloneNode(true);
    var junk = c.querySelectorAll('.msg-avatar,[class*="avatar"],[class*="typing"],.spinner,button,.chat-pdf-btn,.msg-rating,.msg-time,svg,[id*="typing"],.olismo-export-bar');
    for (var i = 0; i < junk.length; i++) junk[i].remove();
    return c;
  }

  function roleOf(el) {
    var cl = (el.className || "") + " " + ((el.getAttribute && el.getAttribute("data-role")) || "");
    if (/\b(user|tu|utente)\b/i.test(cl)) return "Tu";
    return "Assistente AI";
  }

  function collect() {
    var cont = findContainer();
    if (!cont) return { empty: true };
    var wraps = cont.querySelectorAll(WRAP_SEL), parts = [], i;
    if (wraps.length) {
      for (i = 0; i < wraps.length; i++) {
        var w = wraps[i];
        var bubble = w.querySelector(BUBBLE_SEL) || w;
        var inner = clean(bubble).innerHTML.trim();
        if (!inner) continue;
        parts.push('<div class="exp-role">' + roleOf(w) + '</div>' + inner);
      }
    } else {
      var bubbles = cont.querySelectorAll(BUBBLE_SEL);
      if (bubbles.length) {
        for (i = 0; i < bubbles.length; i++) {
          var cb = clean(bubbles[i]).innerHTML.trim();
          if (cb) parts.push(cb);
        }
      } else {
        var whole = clean(cont).innerHTML.trim();
        if (whole) parts.push(whole);
      }
    }
    if (!parts.length) return { empty: true };
    return { html: parts.join("\n<hr class='exp-sep'>\n") };
  }

  function docTitle() {
    var h1 = document.querySelector("h1");
    var t = (h1 && h1.textContent.trim()) || document.title || "Consulenza";
    return t.replace(/\s*\|.*$/, "").replace(/[\\/:*?"<>]+/g, "").trim().slice(0, 80) || "Consulenza";
  }

  function stamp() {
    var d = new Date();
    return d.toLocaleDateString("it-IT") + " " + d.toLocaleTimeString("it-IT", { hour: "2-digit", minute: "2-digit" });
  }

  var CSS =
    "table{border-collapse:collapse;width:100%;margin:.7em 0}" +
    "th,td{border:1px solid #b9b0a0;padding:6px 10px;text-align:left;vertical-align:top;font-size:10.5pt}" +
    "th{background:#2d2a26;color:#f7f2ea;font-weight:600}tr:nth-child(even) td{background:#f7f4ee}" +
    "h1,h2,h3,h4{font-family:Georgia,serif;color:#1a1510;margin:.8em 0 .3em}" +
    "ul,ol{margin:.3em 0 .6em 1.2em}li{margin:.15em 0}strong{color:#1a1510}" +
    "code{background:#f0ece4;padding:1px 5px;border-radius:3px;font-family:Consolas,monospace}" +
    ".exp-role{font-family:Georgia,serif;font-weight:bold;text-transform:uppercase;letter-spacing:.08em;font-size:9pt;color:#8b6914;margin:1.1em 0 .25em;border-bottom:1px solid #e2d8c6;padding-bottom:2px}" +
    ".exp-sep{border:none;border-top:1px dashed #d8cdb8;margin:1.1em 0}" +
    ".exp-head{border-bottom:2px solid #b8935a;padding-bottom:8px;margin-bottom:16px}" +
    ".exp-head h1{margin:0;font-size:18pt}.exp-brand{font-size:9pt;color:#8b6914;letter-spacing:.12em;text-transform:uppercase}" +
    ".exp-foot{margin-top:22px;padding-top:8px;border-top:1px solid #e2d8c6;font-size:8.5pt;color:#7a7266}";

  function header(t) {
    return '<div class="exp-head"><div class="exp-brand">Olismo Integrato - Avv. Carlo Alberto Calcagno</div><h1>' +
      t + '</h1><div style="font-size:9pt;color:#7a7266">Generato il ' + stamp() + '</div></div>';
  }
  function footer() {
    return '<div class="exp-foot">Documento generato da olismo-integrato.it. I contenuti hanno finalita informativa e non sostituiscono una consulenza legale, medica o psicologica personalizzata.</div>';
  }

  function exportPDF() {
    var data = collect();
    if (data.empty) { alert("Nessuna risposta da esportare: fai prima una domanda al motore."); return; }
    var t = docTitle(), w = window.open("", "_blank");
    if (!w) { alert("Consenti le finestre pop-up per esportare in PDF."); return; }
    var d = '<!DOCTYPE html><html lang="it"><head><meta charset="utf-8"><title>' + t +
      '</title><style>@page{margin:1.6cm}body{font-family:Georgia,serif;font-size:11.5pt;line-height:1.55;color:#241f18;max-width:820px;margin:0 auto;padding:1cm}p{margin:.4em 0}' +
      CSS + '</style></head><body>' + header(t) + data.html + footer() +
      '<scr' + 'ipt>window.onload=function(){setTimeout(function(){window.focus();window.print();},350);};</scr' + 'ipt></body></html>';
    w.document.open(); w.document.write(d); w.document.close();
  }

  function exportWord() {
    var data = collect();
    if (data.empty) { alert("Nessuna risposta da esportare: fai prima una domanda al motore."); return; }
    var t = docTitle();
    var html = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><title>' +
      t + '</title><style>body{font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#241f18}' + CSS +
      '</style></head><body>' + header(t) + data.html + footer() + '</body></html>';
    var blob = new Blob(["﻿", html], { type: "application/msword" });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = t.replace(/\s+/g, "_") + ".doc";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 5000);
  }

  function ensureBar() {
    var bar = document.getElementById("olismo-export-bar");
    if (!bar) {
      bar = document.createElement("div");
      bar.id = "olismo-export-bar";
      bar.className = "olismo-export-bar";
      bar.style.cssText = "position:fixed;left:50%;transform:translateX(-50%);bottom:14px;z-index:9998;display:none;gap:8px;align-items:center;background:rgba(255,255,255,.94);border:1px solid #d8cdb8;border-radius:24px;padding:6px 8px;box-shadow:0 4px 16px rgba(0,0,0,.14)";
      var bs = "border:none;cursor:pointer;font-family:'Outfit',sans-serif;font-size:.78rem;font-weight:600;padding:.5rem .95rem;border-radius:18px;color:#fff;white-space:nowrap;";
      bar.innerHTML = '<span style="font-size:.7rem;color:#8b6914;font-weight:700;letter-spacing:.06em;padding-left:6px">ESPORTA</span>' +
        '<button id="olExpPdf" style="' + bs + 'background:#b8935a">PDF</button>' +
        '<button id="olExpWord" style="' + bs + 'background:#2d6a6a">Word</button>';
      document.body.appendChild(bar);
      document.getElementById("olExpPdf").addEventListener("click", exportPDF);
      document.getElementById("olExpWord").addEventListener("click", exportWord);
    }
    return bar;
  }

  function refresh() {
    var bar = ensureBar();
    var data = collect();
    bar.style.display = data.empty ? "none" : "flex";
  }

  window.olismoExportPDF = exportPDF;
  window.olismoExportWord = exportWord;

  function init() { ensureBar(); refresh(); setInterval(refresh, 2500); }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();

olismo-profilo.js:
/* ═══════════════════════════════════════════════════════════════════════
   OLISMO INTEGRATO — Sistema Profilo Integrato (motori → Consulente AI)
   © 2026 Avv. Carlo Alberto Calcagno · olismo-integrato.it

   Helper condiviso che permette a OGNI motore del portale di:
   1) Salvare il proprio risultato in localStorage in formato standard
   2) Esporre un pulsante "Invia al Consulente AI" coerente
   3) Permettere alla pagina "Il mio profilo" di aggregare tutto
   4) Consegnare al Consulente AI un mega-prompt integrato con un solo clic

   Compatibile con olismo-core.js (legge anche le chiavi storiche
   frutti/at/ego/vak/check/trans/diet via adattatore legacy).

   Convenzione localStorage:
     chiave  = `olismo_profile_<motore>`
     valore  = JSON.stringify({
                 motore, titolo, emoji, data,
                 sintesi, dettagli, prompt
               })

   I dati restano ESCLUSIVAMENTE sul dispositivo dell'utente.
═══════════════════════════════════════════════════════════════════════ */

(function (global) {
  'use strict';

  var KEY_PREFIX = 'olismo_profile_';
  var CONSULENTE_URL = 'consulente.html';

  // ─── Registro centrale dei motori (etichette, emoji, ordine) ──────
  var REGISTRO_MOTORI = {
    enneagramma:        { titolo: 'Enneagramma Evolutivo',         emoji: '🌀', ordine: 10 },
    egogramma:          { titolo: 'Egogramma di Berne (AT)',       emoji: '🎭', ordine: 20 },
    adattamenti:        { titolo: 'Adattamenti AT',                emoji: '🧩', ordine: 25 },
    copione:            { titolo: 'Copione di vita (AT)',          emoji: '📜', ordine: 26 },
    transazioni:        { titolo: 'Vettore comunicativo (AT)',     emoji: '↔️', ordine: 27 },
    carezze:            { titolo: 'Economia delle carezze',        emoji: '🤝', ordine: 28 },
    matrice:            { titolo: 'Matrice della svalutazione',    emoji: '◰', ordine: 29 },
    frutti:             { titolo: 'Test dei 9 Frutti (Enneagramma)', emoji: '🍎', ordine: 30 },
    chakra:             { titolo: 'Profilo Chakra',                emoji: '🪷', ordine: 40 },
    cristalli:          { titolo: 'Cristalli e pietre',            emoji: '💎', ordine: 50 },
    bach:               { titolo: 'Fiori di Bach',                 emoji: '🌸', ordine: 60 },
    fes:                { titolo: 'Fiori californiani (FES)',      emoji: '🌼', ordine: 61 },
    bush:               { titolo: 'Fiori australiani (Bush)',      emoji: '🌺', ordine: 62 },
    diet:               { titolo: 'Piano alimentare olistico',     emoji: '🌿', ordine: 65 },
    frequenze:          { titolo: 'Frequenze Solfeggio',           emoji: '🎵', ordine: 70 },
    vak:                { titolo: 'Sistema VAK',                   emoji: '👁️', ordine: 80 },
    violenza:           { titolo: 'Riconoscere la violenza',       emoji: '🛡', ordine: 90 },
    psicoanalogica:     { titolo: 'Psicologia Analogica',          emoji: '🎼', ordine: 95 },
    check:              { titolo: 'Check Integrato',               emoji: '✦', ordine: 100 },
    empowerment:        { titolo: 'Empowerment Mediazione',        emoji: '⚡', ordine: 110 },
    consulente_mediatore: { titolo: 'Consulente Mediatore AI',     emoji: '⚖️', ordine: 120 }
  };

  // ─── Adattatore legacy: chiavi storiche di olismo-core.js ─────────
  // olismo-core.js salva con strutture eterogenee senza campo 'sintesi'.
  // Qui le normalizziamo on-the-fly affinché compaiano nel profilo integrato.
  var REGISTRO_LEGACY = {
    frutti: { motore: 'frutti',      titolo: 'Test dei 9 Frutti (Enneagramma)',   emoji: '🍎', ordine: 30 },
    at:     { motore: 'adattamenti', titolo: 'Adattamenti di personalità AT',     emoji: '🧩', ordine: 25 },
    ego:    { motore: 'egogramma',   titolo: 'Egogramma di Berne',                emoji: '🎭', ordine: 20 },
    vak:    { motore: 'vak',         titolo: 'Canale VAK',                        emoji: '👁️', ordine: 80 },
    check:  { motore: 'check',       titolo: 'Check Integrato',                   emoji: '✦', ordine: 100 },
    trans:  { motore: 'transazioni', titolo: 'Vettore comunicativo (AT)',         emoji: '↔️', ordine: 27 },
    diet:   { motore: 'diet',        titolo: 'Piano alimentare olistico',         emoji: '🌿', ordine: 65 }
  };

  // ─── Utility ──────────────────────────────────────────────────────
  function oggi() {
    var d = new Date();
    return d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
  }
  function safeJSON(str) { try { return JSON.parse(str); } catch (e) { return null; } }
  function storageOk() {
    try { var t = '__olismo_test__'; localStorage.setItem(t, '1'); localStorage.removeItem(t); return true; }
    catch (e) { return false; }
  }

  // ─── Costruzione sintesi/prompt per record legacy ─────────────────
  function _legacySintesi(key, d) {
    if (!d) return null;
    var bits = [];
    if (key === 'frutti') {
      if (d.tipo) bits.push('enneatipo T' + d.tipo + (d.nome ? ' (' + d.nome + ')' : ''));
      if (d.tipo2) bits.push('2° tipo T' + d.tipo2);
      if (d.ala) bits.push('ala dominante ' + d.ala);
    } else if (key === 'at') {
      if (d.primario) bits.push('primario ' + d.primario + (d.primario_pct ? ' (' + d.primario_pct + '%)' : ''));
      if (d.secondario) bits.push('secondario ' + d.secondario + (d.secondario_pct ? ' (' + d.secondario_pct + '%)' : ''));
      if (d.prevalenza) bits.push('prevalenza ' + d.prevalenza);
    } else if (key === 'ego') {
      if (d.dominante) bits.push('dominante ' + d.dominante + (d.dominante_val ? ' (' + d.dominante_val + '/10)' : ''));
      if (d.minimo) bits.push('più basso ' + d.minimo + (d.minimo_val ? ' (' + d.minimo_val + '/10)' : ''));
    } else if (key === 'vak') {
      if (d.canale) bits.push('canale dominante ' + d.canale + (d.pct ? ' (' + d.pct + '%)' : ''));
      if (d.secondo) bits.push('2° canale ' + d.secondo);
    } else if (key === 'check') {
      if (d.enneatipo) bits.push('enneatipo ipotesi T' + d.enneatipo);
      if (d.enn2) bits.push('2° enneatipo T' + d.enn2);
      if (d.vak) bits.push('canale VAK ' + d.vak);
      if (d.at_stato) bits.push('stato AT ' + d.at_stato);
      if (d.chakra_forte) bits.push('chakra di forza ' + d.chakra_forte);
      if (d.chakra_debole) bits.push('chakra da lavorare ' + d.chakra_debole);
      if (d.spinte && d.spinte.length) bits.push('spinte ' + d.spinte.join(', '));
      if (d.conf_stile) bits.push('stile conflitto ' + d.conf_stile);
    } else if (key === 'trans') {
      if (d.vettore_primario) bits.push('vettore primario ' + d.vettore_primario + (d.pct_primario ? ' (' + d.pct_primario + '%)' : ''));
      if (d.vettore_sec) bits.push('vettore secondario ' + d.vettore_sec);
    } else if (key === 'diet') {
      if (d.tipo) bits.push('piano per T' + d.tipo + (d.adattamento ? ' / ' + d.adattamento : ''));
    }
    if (!bits.length) return null;
    return { sintesi: bits.join('; '), data: d._date || '' };
  }

  function _legacyPrompt(key, d, sintesi) {
    var info = REGISTRO_LEGACY[key];
    var titolo = info ? info.titolo : key;
    var data = d && d._date ? ' del ' + d._date : '';
    return 'Profilo ' + titolo + data + ': ' + sintesi +
      '. Puoi commentare questo risultato in chiave olistica e collegarlo agli altri test del mio profilo?';
  }

  // ─── API: ACCUMULA una voce nello storico di un motore ────────────
  // Per motori "di consultazione ripetuta" (frequenze, fiori, cristalli):
  // ogni volta che l'utente consulta un problema, lo registriamo.
  // Manteniamo solo le ultime MAX_STORICO voci.
  var MAX_STORICO = 10;
  function accumula(motore, voce) {
    if (!storageOk() || !motore || !voce) return false;
    var reg = REGISTRO_MOTORI[motore] || { titolo: motore, emoji: '◉', ordine: 999 };
    var raw = localStorage.getItem(KEY_PREFIX + motore);
    var rec = raw ? safeJSON(raw) : null;
    var ora = new Date().toISOString().slice(0, 16).replace('T', ' ');
    var nuovaVoce = {
      ora: ora,
      problema: String(voce.problema || '').slice(0, 280),
      esito:    String(voce.esito || voce.risultato || '').slice(0, 500),
      extra:    voce.extra || null
    };
    if (!rec || !rec.storico) {
      rec = {
        motore: motore,
        titolo: voce.titolo || reg.titolo,
        emoji:  voce.emoji  || reg.emoji,
        data:   oggi(),
        storico: [],
        sintesi: '',
        prompt: '',
        dettagli: null
      };
    }
    rec.storico.unshift(nuovaVoce);
    rec.storico = rec.storico.slice(0, MAX_STORICO);
    rec.data = oggi();
    // Ricostruisce sintesi e prompt dal nuovo storico
    var nProblemi = rec.storico.length;
    var ultimi = rec.storico.slice(0, 5).map(function (v) {
      return v.problema + (v.esito ? ' → ' + v.esito.split('\n')[0].slice(0, 80) : '');
    });
    rec.sintesi = (nProblemi === 1 ? '1 consultazione' : nProblemi + ' consultazioni') +
      ' registrate. Tematiche ricorrenti: ' + ultimi.join('; ');
    rec.prompt = 'Ho consultato ' + (reg.titolo || motore) + ' su ' + nProblemi + ' tematiche.\n\n' +
      'STORICO (dalla più recente):\n' +
      rec.storico.map(function (v, i) {
        return (i + 1) + ') [' + v.ora + '] ' + v.problema + (v.esito ? '\n   → ' + v.esito : '');
      }).join('\n') +
      '\n\nNoti un pattern in queste consultazioni? Quali nodi ricorrenti vedi? Cosa mi suggerisci sul piano evolutivo?';
    try {
      localStorage.setItem(KEY_PREFIX + motore, JSON.stringify(rec));
      try { global.dispatchEvent(new CustomEvent('olismo:profilo:aggiornato', { detail: rec })); } catch (e) {}
      return true;
    } catch (e) { return false; }
  }

  // ─── API: SALVA un risultato motore ───────────────────────────────
  function salva(motore, payload) {
    if (!storageOk() || !motore) return false;
    payload = payload || {};
    var reg = REGISTRO_MOTORI[motore] || { titolo: motore, emoji: '◉', ordine: 999 };
    var record = {
      motore: motore,
      titolo: payload.titolo || reg.titolo,
      emoji:  payload.emoji  || reg.emoji,
      data:   payload.data   || oggi(),
      sintesi:  String(payload.sintesi || '').slice(0, 800),
      dettagli: payload.dettagli || null,
      prompt:   String(payload.prompt || payload.sintesi || '').slice(0, 2000)
    };
    try {
      localStorage.setItem(KEY_PREFIX + motore, JSON.stringify(record));
      try { global.dispatchEvent(new CustomEvent('olismo:profilo:aggiornato', { detail: record })); } catch (e) {}
      return true;
    } catch (e) { return false; }
  }

  // ─── API: LEGGI un singolo motore ─────────────────────────────────
  function leggi(motore) {
    if (!storageOk()) return null;
    var raw = localStorage.getItem(KEY_PREFIX + motore);
    var rec = raw ? safeJSON(raw) : null;
    if (rec && rec.sintesi) return rec;
    // Tenta legacy: motore corrisponde a una chiave legacy?
    var legacyKey = null;
    Object.keys(REGISTRO_LEGACY).forEach(function (lk) {
      if (REGISTRO_LEGACY[lk].motore === motore) legacyKey = lk;
    });
    if (legacyKey) {
      var legRaw = localStorage.getItem(KEY_PREFIX + legacyKey);
      var legRec = legRaw ? safeJSON(legRaw) : null;
      if (legRec) {
        var s = _legacySintesi(legacyKey, legRec);
        if (s) {
          var info = REGISTRO_LEGACY[legacyKey];
          return {
            motore: info.motore, titolo: info.titolo, emoji: info.emoji,
            data: s.data, sintesi: s.sintesi,
            prompt: _legacyPrompt(legacyKey, legRec, s.sintesi),
            dettagli: legRec
          };
        }
      }
    }
    return null;
  }

  // ─── API: LEGGI TUTTI i motori compilati ──────────────────────────
  function leggiTutti() {
    if (!storageOk()) return [];
    var out = [];
    var seen = {};
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (!k || k.indexOf(KEY_PREFIX) !== 0) continue;
      var keyShort = k.substring(KEY_PREFIX.length);
      var rec = safeJSON(localStorage.getItem(k));
      if (!rec) continue;
      // Formato nuovo
      if (rec.sintesi && rec.motore) {
        if (seen[rec.motore]) continue;
        out.push(rec);
        seen[rec.motore] = true;
        continue;
      }
      // Formato legacy
      if (REGISTRO_LEGACY[keyShort]) {
        var info = REGISTRO_LEGACY[keyShort];
        if (seen[info.motore]) continue;
        var s = _legacySintesi(keyShort, rec);
        if (!s) continue;
        out.push({
          motore: info.motore, titolo: info.titolo, emoji: info.emoji,
          data: s.data, sintesi: s.sintesi,
          prompt: _legacyPrompt(keyShort, rec, s.sintesi),
          dettagli: rec
        });
        seen[info.motore] = true;
      }
    }
    out.sort(function (a, b) {
      var oa = (REGISTRO_MOTORI[a.motore] || {}).ordine || 999;
      var ob = (REGISTRO_MOTORI[b.motore] || {}).ordine || 999;
      return oa - ob;
    });
    return out;
  }

  // ─── API: CANCELLA un motore ──────────────────────────────────────
  function cancella(motore) {
    if (!storageOk()) return false;
    try {
      localStorage.removeItem(KEY_PREFIX + motore);
      // Cancella anche eventuale chiave legacy associata
      Object.keys(REGISTRO_LEGACY).forEach(function (lk) {
        if (REGISTRO_LEGACY[lk].motore === motore) {
          try { localStorage.removeItem(KEY_PREFIX + lk); } catch (e) {}
        }
      });
      return true;
    } catch (e) { return false; }
  }

  // ─── API: CANCELLA TUTTI i profili ────────────────────────────────
  function cancellaTutti() {
    if (!storageOk()) return false;
    var keys = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf(KEY_PREFIX) === 0) keys.push(k);
    }
    keys.forEach(function (k) { try { localStorage.removeItem(k); } catch (e) {} });
    return true;
  }

  // ─── API: COSTRUISCI il mega-prompt integrato ─────────────────────
  function costruisciPromptIntegrato() {
    var tutti = leggiTutti();
    if (!tutti.length) return null;
    var lines = [];
    lines.push('Ciao Consulente. Ti invio il mio profilo olistico integrato, raccolto dai motori che ho compilato sul portale Olismo Integrato. Per favore leggi tutti i dati insieme — non uno alla volta — e dammi una consulenza che metta in relazione gli aspetti psicologici, energetici e comportamentali. Evidenzia: risorse principali, nodi su cui lavorare, suggerimenti pratici (con eventuali fiori, cristalli, frequenze, esercizi AT) e — se pertinente — implicazioni per la gestione del conflitto o di una mediazione in corso.');
    lines.push('');
    lines.push('PROFILI COMPILATI (' + tutti.length + ')');
    lines.push('═══════════════════════════════════════');
    tutti.forEach(function (p, idx) {
      lines.push('');
      lines.push((idx + 1) + '. ' + (p.emoji || '◉') + ' ' + (p.titolo || p.motore).toUpperCase() + '  (' + (p.data || '') + ')');
      lines.push('───────────────────────────────────────');
      lines.push(p.sintesi || '(nessuna sintesi)');
    });
    lines.push('');
    lines.push('═══════════════════════════════════════');
    lines.push('Grazie. Procedi con la consulenza integrata.');
    return lines.join('\n');
  }

  // ─── API: INVIA TUTTO al Consulente AI ────────────────────────────
  function inviaTuttoAlConsulente() {
    var prompt = costruisciPromptIntegrato();
    if (!prompt) {
      alert('Non hai ancora compilato nessun test sul portale. Comincia da uno strumento di lettura dal menu principale.');
      return;
    }
    try {
      sessionStorage.setItem('olismo_prompt_integrato', prompt);
      location.href = CONSULENTE_URL + '?profilo=integrato';
    } catch (e) {
      location.href = CONSULENTE_URL + '?prompt=' + encodeURIComponent(prompt.slice(0, 7000));
    }
  }

  // ─── API: invia un singolo profilo al Consulente ──────────────────
  function inviaProfiloAlConsulente(motore) {
    var p = leggi(motore);
    if (!p) { alert('Profilo non disponibile.'); return; }
    var promptText = p.prompt || ('Analizza il mio profilo ' + p.titolo + ':\n\n' + p.sintesi);
    try {
      sessionStorage.setItem('olismo_prompt_singolo', promptText);
      location.href = CONSULENTE_URL + '?profilo=' + encodeURIComponent(motore);
    } catch (e) {
      location.href = CONSULENTE_URL + '?prompt=' + encodeURIComponent(promptText.slice(0, 7000));
    }
  }

  // ─── API: il Consulente legge il prompt all'arrivo ────────────────
  function recuperaPromptDaURL() {
    var params = new URLSearchParams(location.search);
    var modo = params.get('profilo');
    if (!modo) return null;
    try {
      if (modo === 'integrato') return sessionStorage.getItem('olismo_prompt_integrato');
      return sessionStorage.getItem('olismo_prompt_singolo');
    } catch (e) { return null; }
  }

  // ─── API: monta CTA "Invia al Consulente" ─────────────────────────
  function montaPulsanteConsulente(opts) {
    opts = opts || {};
    var motore = opts.motore;
    if (!motore) return;
    var container = document.querySelector(opts.containerSelector || '#olismo-cta-consulente');
    if (!container) {
      container = document.createElement('div');
      container.id = 'olismo-cta-consulente';
      container.style.cssText = 'margin:2.5rem auto 1.5rem;padding:1.5rem;max-width:720px;text-align:center;background:linear-gradient(135deg,#fff8e8,#fefaf0);border:1px solid #d4af37;border-radius:12px;box-shadow:0 2px 12px rgba(180,140,30,.08)';
      document.body.appendChild(container);
    }
    container.innerHTML =
      '<div style="font-family:\'Cormorant Garamond\',Georgia,serif;font-size:1.2rem;color:#8b6914;margin-bottom:.4rem">✦ Vuoi un\'analisi personalizzata?</div>' +
      '<p style="font-family:\'EB Garamond\',Georgia,serif;font-size:1rem;color:#444;margin:0 auto 1rem;max-width:560px;line-height:1.55">' +
      'Invia questo risultato al <strong>Consulente AI</strong> per un commento approfondito. ' +
      'Puoi anche andare a <a href="il-mio-profilo.html" style="color:#b8860b">Il mio profilo</a> ' +
      'e chiedere una <strong>consulenza integrata</strong> su tutti i test che hai compilato.' +
      '</p>' +
      '<div style="display:flex;gap:.6rem;flex-wrap:wrap;justify-content:center">' +
      '<button type="button" data-olismo-invia="' + motore + '" ' +
      'style="display:inline-flex;align-items:center;gap:.5rem;padding:.75rem 1.5rem;background:#b8860b;color:#fff;border:none;border-radius:24px;font-family:\'Outfit\',system-ui,sans-serif;font-size:.95rem;font-weight:600;cursor:pointer;transition:opacity .2s">' +
      '🤖 Invia al Consulente AI</button>' +
      '<a href="il-mio-profilo.html" ' +
      'style="display:inline-flex;align-items:center;gap:.5rem;padding:.75rem 1.5rem;background:transparent;color:#b8860b;border:1.5px solid #b8860b;border-radius:24px;font-family:\'Outfit\',system-ui,sans-serif;font-size:.95rem;font-weight:600;text-decoration:none">' +
      '📊 Il mio profilo</a>' +
      '</div>';
    var btn = container.querySelector('[data-olismo-invia]');
    if (btn) btn.addEventListener('click', function () { inviaProfiloAlConsulente(motore); });
  }

  // ─── Espone l'API globale ─────────────────────────────────────────
  global.OlismoProfilo = {
    salva: salva,
    accumula: accumula,
    leggi: leggi,
    leggiTutti: leggiTutti,
    cancella: cancella,
    cancellaTutti: cancellaTutti,
    inviaTuttoAlConsulente: inviaTuttoAlConsulente,
    inviaProfiloAlConsulente: inviaProfiloAlConsulente,
    costruisciPromptIntegrato: costruisciPromptIntegrato,
    recuperaPromptDaURL: recuperaPromptDaURL,
    montaPulsanteConsulente: montaPulsanteConsulente,
    registro: REGISTRO_MOTORI
  };

})(window);

olismo-mediazione.js:
/* ═══════════════════════════════════════════════════════════════════════
   OLISMO INTEGRATO — Sistema Profilo MEDIAZIONE multi-soggetto
   © 2026 Avv. Carlo Alberto Calcagno · olismo-integrato.it

   Sotto-sistema per tracciare PIÙ SOGGETTI in un dossier di mediazione.
   Tipico caso d'uso del Mediatore/Avvocato:
     1. Crea un dossier (es. "Famiglia Rossi")
     2. Aggiunge i soggetti (es. "Madre Anna", "Padre Marco", "Figlia Sara")
     3. Per ogni soggetto compila enneatipo, AT, VAK, chakra prevalente,
        stile di conflitto, copione, note
     4. Invia tutto al Consulente Mediatore AI con un solo clic per
        ottenere una lettura sistemica

   Storage: olismo_mediazione_dossier_<id>
   Dossier corrente: olismo_mediazione_dossier_corrente
═══════════════════════════════════════════════════════════════════════ */

(function (global) {
  'use strict';

  var MED_PREFIX = 'olismo_mediazione_dossier_';
  var MED_CURRENT = 'olismo_mediazione_dossier_corrente';
  var CONSULENTE_MED_URL = 'consulente-mediatore.html';

  function oggi() {
    var d = new Date();
    return d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
  }
  function safeJSON(str) { try { return JSON.parse(str); } catch (e) { return null; } }
  function storageOk() {
    try { var t = '__olismo_test__'; localStorage.setItem(t, '1'); localStorage.removeItem(t); return true; }
    catch (e) { return false; }
  }
  function idDossier() {
    return 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }
  function idSoggetto() {
    return 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
  }
  function s(str, max) { return String(str == null ? '' : str).slice(0, max || 200); }

  // ─── Crea nuovo dossier ───────────────────────────────────────────
  function creaDossier(nome, tipo, note) {
    if (!storageOk()) return null;
    var dossier = {
      id: idDossier(),
      nome: s(nome || 'Dossier ' + oggi(), 120),
      tipo: tipo || 'famigliare',  // famigliare | coppia | civile | commerciale | altro
      note: s(note, 1000),
      creato: oggi(),
      aggiornato: oggi(),
      soggetti: [],
      eventi: []  // facoltativo — log di accadimenti significativi durante la mediazione
    };
    try {
      localStorage.setItem(MED_PREFIX + dossier.id, JSON.stringify(dossier));
      localStorage.setItem(MED_CURRENT, dossier.id);
      return dossier;
    } catch (e) { return null; }
  }

  function leggiDossier(id) {
    if (!storageOk() || !id) return null;
    var raw = localStorage.getItem(MED_PREFIX + id);
    return raw ? safeJSON(raw) : null;
  }

  function salvaDossier(dossier) {
    if (!storageOk() || !dossier || !dossier.id) return false;
    dossier.aggiornato = oggi();
    try {
      localStorage.setItem(MED_PREFIX + dossier.id, JSON.stringify(dossier));
      return true;
    } catch (e) { return false; }
  }

  function listaDossier() {
    if (!storageOk()) return [];
    var out = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf(MED_PREFIX) === 0 && k !== MED_CURRENT) {
        var d = safeJSON(localStorage.getItem(k));
        if (d && d.id) out.push(d);
      }
    }
    out.sort(function (a, b) { return (b.aggiornato || '').localeCompare(a.aggiornato || ''); });
    return out;
  }

  function cancellaDossier(id) {
    if (!storageOk()) return false;
    try {
      localStorage.removeItem(MED_PREFIX + id);
      if (localStorage.getItem(MED_CURRENT) === id) localStorage.removeItem(MED_CURRENT);
      return true;
    } catch (e) { return false; }
  }

  function getCorrente() {
    if (!storageOk()) return null;
    var id = localStorage.getItem(MED_CURRENT);
    return id ? leggiDossier(id) : null;
  }
  function setCorrente(id) {
    if (!storageOk()) return false;
    if (id) localStorage.setItem(MED_CURRENT, id);
    else localStorage.removeItem(MED_CURRENT);
    return true;
  }

  // ─── Soggetti ─────────────────────────────────────────────────────
  function aggiungiSoggetto(dossierId, soggetto) {
    var d = leggiDossier(dossierId);
    if (!d) return null;
    soggetto = soggetto || {};
    var sogg = {
      id: idSoggetto(),
      nome: s(soggetto.nome || 'Soggetto ' + (d.soggetti.length + 1), 80),
      ruolo: s(soggetto.ruolo, 60),
      eta: soggetto.eta || '',
      enneatipo: s(soggetto.enneatipo, 40),
      adattamento: s(soggetto.adattamento, 60),
      stato_at: s(soggetto.stato_at, 40),
      vak: s(soggetto.vak, 30),
      chakra_forte: s(soggetto.chakra_forte, 40),
      chakra_debole: s(soggetto.chakra_debole, 40),
      copione: s(soggetto.copione, 200),
      stile_conflitto: s(soggetto.stile_conflitto, 80),
      svalutazione: s(soggetto.svalutazione, 200),
      note: s(soggetto.note, 600),
      reddito_mensile: s(soggetto.reddito_mensile, 30),
      patrimonio: s(soggetto.patrimonio, 200),
      spese_fisse: s(soggetto.spese_fisse, 200),
      capacita_lavorativa: s(soggetto.capacita_lavorativa, 100),
      residenza: s(soggetto.residenza, 100),
      stato_civile: s(soggetto.stato_civile, 40),
      tempo_attuale_figli: s(soggetto.tempo_attuale_figli, 100),
      disponibilita_oraria: s(soggetto.disponibilita_oraria, 200)
    };
    d.soggetti.push(sogg);
    salvaDossier(d);
    return sogg;
  }

  function aggiornaSoggetto(dossierId, soggettoId, patch) {
    var d = leggiDossier(dossierId);
    if (!d) return null;
    var idx = d.soggetti.findIndex(function (x) { return x.id === soggettoId; });
    if (idx < 0) return null;
    Object.keys(patch || {}).forEach(function (k) {
      if (k !== 'id') d.soggetti[idx][k] = patch[k];
    });
    salvaDossier(d);
    return d.soggetti[idx];
  }

  function rimuoviSoggetto(dossierId, soggettoId) {
    var d = leggiDossier(dossierId);
    if (!d) return false;
    d.soggetti = d.soggetti.filter(function (x) { return x.id !== soggettoId; });
    salvaDossier(d);
    return true;
  }

  // ─── Riempi un soggetto coi dati del profilo personale ────────────
  // Permette al mediatore di mappare i propri test su se stesso o
  // su un soggetto generico
  function riempiDaProfiloPersonale(dossierId, soggettoId) {
    if (!global.OlismoProfilo) return null;
    var tutti = OlismoProfilo.leggiTutti();
    if (!tutti.length) return null;
    var patch = {};
    tutti.forEach(function (p) {
      var det = p.dettagli || {};
      if (p.motore === 'frutti' && det.tipo) patch.enneatipo = 'T' + det.tipo + (det.tipo2 ? '/T' + det.tipo2 : '') + (det.ala ? ' (' + det.ala + ')' : '');
      if (p.motore === 'adattamenti' && det.primario) patch.adattamento = det.primario + (det.secondario ? ' / ' + det.secondario : '');
      if (p.motore === 'egogramma' && det.dominante) patch.stato_at = 'dominante ' + det.dominante + (det.minimo ? ' · carente ' + det.minimo : '');
      if (p.motore === 'vak' && det.canale) patch.vak = det.canale + (det.pct ? ' (' + det.pct + '%)' : '');
      if (p.motore === 'check') {
        if (det.enneatipo && !patch.enneatipo) patch.enneatipo = 'T' + det.enneatipo + (det.enn2 ? '/T' + det.enn2 : '');
        if (det.vak && !patch.vak) patch.vak = det.vak;
        if (det.at_stato && !patch.stato_at) patch.stato_at = det.at_stato;
        if (det.chakra_forte) patch.chakra_forte = det.chakra_forte;
        if (det.chakra_debole) patch.chakra_debole = det.chakra_debole;
        if (det.conf_stile) patch.stile_conflitto = det.conf_stile;
      }
    });
    if (Object.keys(patch).length === 0) return null;
    return aggiornaSoggetto(dossierId, soggettoId, patch);
  }

  // ─── Mega-prompt per il Consulente Mediatore AI ───────────────────
  function costruisciPrompt(dossierId) {
    var d = leggiDossier(dossierId);
    if (!d) return null;
    var L = [];
    L.push('Ciao Consulente Mediatore. Ti sottopongo un dossier di mediazione su cui ti chiedo una lettura sistemica:');
    L.push('');
    L.push('DOSSIER: ' + d.nome);
    L.push('Tipo: ' + d.tipo + '  ·  Creato: ' + d.creato + '  ·  Aggiornato: ' + d.aggiornato);
    if (d.note) L.push('Note di caso: ' + d.note);
    L.push('');
    L.push('SOGGETTI COINVOLTI (' + d.soggetti.length + ')');
    L.push('═══════════════════════════════════════');
    d.soggetti.forEach(function (sg, i) {
      L.push('');
      L.push((i + 1) + '. ' + sg.nome + (sg.ruolo ? ' — ' + sg.ruolo : '') + (sg.eta ? ' (' + sg.eta + ' anni)' : ''));
      L.push('───────────────────────────────────────');
      var p = [];
      if (sg.enneatipo)       p.push('• Enneatipo: ' + sg.enneatipo);
      if (sg.adattamento)     p.push('• Adattamento AT: ' + sg.adattamento);
      if (sg.stato_at)        p.push('• Stato dell\'Io: ' + sg.stato_at);
      if (sg.vak)             p.push('• Canale VAK: ' + sg.vak);
      if (sg.chakra_forte)    p.push('• Chakra di forza: ' + sg.chakra_forte);
      if (sg.chakra_debole)   p.push('• Chakra da lavorare: ' + sg.chakra_debole);
      if (sg.copione)         p.push('• Copione di vita: ' + sg.copione);
      if (sg.stile_conflitto) p.push('• Stile di conflitto: ' + sg.stile_conflitto);
      if (sg.svalutazione)    p.push('• Matrice di svalutazione ricorrente: ' + sg.svalutazione);
      if (p.length === 0) p.push('(nessun dato anagrafico/psicologico compilato)');
      L.push(p.join('\n'));
      var econ = [];
      if (sg.reddito_mensile)     econ.push('reddito ' + sg.reddito_mensile);
      if (sg.capacita_lavorativa) econ.push('capacità lavorativa ' + sg.capacita_lavorativa);
      if (sg.patrimonio)          econ.push('patrimonio: ' + sg.patrimonio);
      if (sg.spese_fisse)         econ.push('spese fisse: ' + sg.spese_fisse);
      if (econ.length) L.push('Quadro economico: ' + econ.join('; '));
      var fam = [];
      if (sg.residenza)             fam.push('residenza ' + sg.residenza);
      if (sg.stato_civile)          fam.push('stato civile ' + sg.stato_civile);
      if (sg.tempo_attuale_figli)   fam.push('tempo con figli ' + sg.tempo_attuale_figli);
      if (sg.disponibilita_oraria)  fam.push('disponibilità oraria ' + sg.disponibilita_oraria);
      if (fam.length) L.push('Quadro familiare/logistico: ' + fam.join('; '));
      if (sg.note) L.push('Note specifiche: ' + sg.note);
    });
    L.push('');
    L.push('═══════════════════════════════════════');
    L.push('Quello che ti chiedo:');
    L.push('1) Leggi i soggetti come SISTEMA, non come individui isolati. Quali dinamiche di incastro vedi (es. complementarietà, collusioni, scapegoat, alleanze trasversali, triangolazioni)?');
    L.push('2) Quali sono le AREE DI CONFLITTO PIÙ PROBABILI fra questi profili e perché (a livello di bisogni, valori, stili comunicativi)?');
    L.push('3) Suggerisci una STRATEGIA DI MEDIAZIONE concreta: ordine di colloqui (separati / congiunti), tono da tenere con ciascuno, leve di motivazione di ognuno, parole-chiave da usare ed evitare, momenti critici a cui prestare attenzione.');
    L.push('4) Indica eventuali RED FLAG (squilibri di potere, sospetto di violenza assistita, manipolazione, sopruso, alienazione genitoriale) e quando sospendere la mediazione o riformularla.');
    L.push('5) Proponi DOMANDE-CHIAVE che il mediatore può usare con ciascun soggetto in seduta per fare emergere bisogni, interessi e opzioni.');
    L.push('6) Se sono presenti minori, indica come tutelarli pur tenendoli nel sistema di lettura.');
    L.push('');
    L.push('Risposta in italiano, professionale, articolata in sezioni, taglio operativo per un mediatore.');
    return L.join('\n');
  }

  function inviaAlConsulente(dossierId) {
    var prompt = costruisciPrompt(dossierId);
    if (!prompt) { alert('Dossier non trovato o vuoto.'); return false; }
    try {
      sessionStorage.setItem('olismo_prompt_mediazione', prompt);
      location.href = CONSULENTE_MED_URL + '?profilo=mediazione&dossier=' + encodeURIComponent(dossierId);
      return true;
    } catch (e) {
      location.href = CONSULENTE_MED_URL + '?prompt=' + encodeURIComponent(prompt.slice(0, 7000));
      return true;
    }
  }

  // ─── Mega-prompt PIANO GENITORIALE ───────────────────────────────
  function costruisciPromptPianoGenitoriale(dossierId) {
    var d = leggiDossier(dossierId);
    if (!d) return null;
    var L = [];
    L.push('Ciao Consulente Mediatore. Costruisci un PIANO GENITORIALE operativo a partire da questo dossier di mediazione familiare.');
    L.push('');
    L.push('DOSSIER: ' + d.nome + (d.note ? '  —  ' + d.note : ''));
    L.push('');
    L.push('GENITORI E ALTRI SOGGETTI ADULTI');
    L.push('═══════════════════════════════════════');
    d.soggetti.forEach(function(sg){
      var r = (sg.ruolo || '').toLowerCase();
      if (r === 'figlio' || r === 'figlia' || r === 'minore' || r === 'figli') return;
      var righe = [sg.nome + (sg.ruolo ? ' (' + sg.ruolo + ')' : '') + (sg.eta ? ' · ' + sg.eta + ' anni' : '')];
      if (sg.enneatipo)            righe.push('enneatipo ' + sg.enneatipo);
      if (sg.stile_conflitto)      righe.push('stile di conflitto: ' + sg.stile_conflitto);
      if (sg.residenza)            righe.push('residenza: ' + sg.residenza);
      if (sg.disponibilita_oraria) righe.push('disponibilità oraria: ' + sg.disponibilita_oraria);
      if (sg.tempo_attuale_figli)  righe.push('tempo attuale con i figli: ' + sg.tempo_attuale_figli);
      if (sg.reddito_mensile)      righe.push('reddito ' + sg.reddito_mensile);
      L.push('• ' + righe.join(' · '));
    });
    var figli = d.soggetti.filter(function(sg){
      var r = (sg.ruolo || '').toLowerCase();
      return r === 'figlio' || r === 'figlia' || r === 'minore' || r === 'figli';
    });
    if (figli.length) {
      L.push('');
      L.push('FIGLI / MINORI COINVOLTI (' + figli.length + ')');
      L.push('═══════════════════════════════════════');
      figli.forEach(function(f){
        var righe = [f.nome + (f.eta ? ' (' + f.eta + ' anni)' : '')];
        if (f.tempo_attuale_figli) righe.push('tempo attuale con genitori: ' + f.tempo_attuale_figli);
        if (f.residenza) righe.push('residenza: ' + f.residenza);
        if (f.note) righe.push('note: ' + f.note);
        L.push('• ' + righe.join(' · '));
      });
    }
    var hasEcon = d.soggetti.some(function(sg){
      return sg.reddito_mensile || sg.patrimonio || sg.spese_fisse;
    });
    if (hasEcon) {
      L.push('');
      L.push('QUADRO ECONOMICO COMPLESSIVO');
      L.push('═══════════════════════════════════════');
      d.soggetti.forEach(function(sg){
        var righe = [];
        if (sg.reddito_mensile) righe.push('reddito mensile ' + sg.reddito_mensile);
        if (sg.patrimonio)      righe.push('patrimonio: ' + sg.patrimonio);
        if (sg.spese_fisse)     righe.push('spese fisse: ' + sg.spese_fisse);
        if (righe.length) L.push('• ' + sg.nome + ' — ' + righe.join('; '));
      });
    }
    L.push('');
    L.push('═══════════════════════════════════════');
    L.push('Quello che ti chiedo — costruisci un PIANO GENITORIALE FUNZIONANTE con queste sezioni:');
    L.push('');
    L.push('1) PRINCIPI GUIDA del piano (centralità del minore, bigenitorialità art. 337-ter c.c., continuità affettiva, riservatezza delle dinamiche di coppia rispetto ai figli).');
    L.push('2) RESIDENZA ABITUALE e CRITERI di scelta della casa familiare alla luce della Cass. SU 13/2014 e della giurisprudenza più recente; collocamento prevalente vs paritario.');
    L.push('3) TEMPI DI PERMANENZA settimanali, week-end alternati, festività (Natale, Pasqua, compleanni, ricorrenze), vacanze estive: proposta concreta con calendario tipo, adattata all’età dei figli e ai turni lavorativi dei genitori.');
    L.push('4) SCUOLA E SALUTE: chi accompagna, chi prende le decisioni di routine, chi quelle di maggiore importanza (artt. 337-ter c.c. e 316 c.c.). Modalità di scambio informazioni.');
    L.push('5) MANTENIMENTO ORDINARIO E STRAORDINARIO: proponi un assegno di mantenimento alla luce dei redditi indicati, dei tempi di permanenza e delle spese fisse, citando i parametri di Cassazione (capacità economica, tenore di vita pregresso, tempi di permanenza, età). Spese straordinarie: elenco esemplificativo, criteri di ripartizione, modalità di concertazione.');
    L.push('6) EVENTUALE ASSEGNO PER IL CONIUGE / ALIMENTI: valuta se ricorrono i presupposti dell’assegno divorzile (Cass. SU 18287/2018, funzione assistenziale + perequativo-compensativa) o dei meri alimenti (art. 433 c.c.); quantifica un range plausibile e indica eventi modificativi.');
    L.push('7) CLAUSOLE DI FLESSIBILITÀ e revisione periodica del piano (es. cadenza annuale, eventi modificativi).');
    L.push('8) GESTIONE DEI CONFLITTI: in base allo stile di conflitto e all’enneatipo dei genitori, suggerisci canali di comunicazione (app condivise, mediazione di ritorno, co-parenting coordinator).');
    L.push('9) TUTELA DEL MINORE: parole da non dire davanti ai figli, segnali di malessere a cui prestare attenzione, indicazione su quando attivare un ascolto del minore o coinvolgere il servizio sociale.');
    L.push('10) RED FLAG: se intravedi indicatori di violenza assistita, alienazione, manipolazione, sopruso economico, segnala come la mediazione debba essere sospesa o riformulata.');
    L.push('11) BOZZA OPERATIVA — chiudi con una proposta sintetica (15-25 righe) in linguaggio comprensibile per le parti, da usare come canovaccio del verbale di accordo.');
    L.push('');
    L.push('Risposta in italiano, professionale, con riferimenti normativi e giurisprudenziali essenziali. Cala le proposte sui dati del dossier, evita le generalità.');
    return L.join('\n');
  }

  function inviaPianoGenitoriale(dossierId) {
    var prompt = costruisciPromptPianoGenitoriale(dossierId);
    if (!prompt) { alert('Dossier non trovato o vuoto.'); return false; }
    try {
      sessionStorage.setItem('olismo_prompt_mediazione', prompt);
      location.href = CONSULENTE_MED_URL + '?profilo=mediazione&dossier=' + encodeURIComponent(dossierId) + '&tipo=piano';
      return true;
    } catch (e) {
      location.href = CONSULENTE_MED_URL + '?prompt=' + encodeURIComponent(prompt.slice(0, 7000));
      return true;
    }
  }

  function recuperaPrompt() {
    try {
      var params = new URLSearchParams(location.search);
      if (params.get('profilo') !== 'mediazione') return null;
      return sessionStorage.getItem('olismo_prompt_mediazione');
    } catch (e) { return null; }
  }

  // ─── Esporta JSON dossier ─────────────────────────────────────────
  function esportaJSON(dossierId) {
    var d = leggiDossier(dossierId);
    if (!d) return null;
    return JSON.stringify(d, null, 2);
  }
  function importaJSON(jsonStr) {
    try {
      var d = JSON.parse(jsonStr);
      if (!d.id) d.id = idDossier();
      if (!Array.isArray(d.soggetti)) d.soggetti = [];
      salvaDossier(d);
      return d;
    } catch (e) { return null; }
  }

  global.OlismoMediazione = {
    creaDossier: creaDossier,
    leggiDossier: leggiDossier,
    salvaDossier: salvaDossier,
    listaDossier: listaDossier,
    cancellaDossier: cancellaDossier,
    getCorrente: getCorrente,
    setCorrente: setCorrente,
    aggiungiSoggetto: aggiungiSoggetto,
    aggiornaSoggetto: aggiornaSoggetto,
    rimuoviSoggetto: rimuoviSoggetto,
    riempiDaProfiloPersonale: riempiDaProfiloPersonale,
    costruisciPrompt: costruisciPrompt,
    costruisciPromptPianoGenitoriale: costruisciPromptPianoGenitoriale,
    inviaAlConsulente: inviaAlConsulente,
    inviaPianoGenitoriale: inviaPianoGenitoriale,
    recuperaPrompt: recuperaPrompt,
    esportaJSON: esportaJSON,
    importaJSON: importaJSON
  };

})(window);

olismo-reset.js:
/**
 * OlismoReset — utility per azzerare i dati locali del portale.
 *
 * Cancella SOLO localStorage e sessionStorage relativi a Olismo Integrato:
 *  • profili dei motori (olismo_profile_*)
 *  • dossier di mediazione (olismo_mediazione_*)
 *  • chiavi legacy di olismo-core.js (quiz_*, frutti_*, vak_*, ecc.)
 *  • prompt temporanei (olismo_prompt_*)
 *
 * Non tocca cookie, IndexedDB, o dati di altri siti.
 * Espone:
 *   OlismoReset.elencaChiavi()  -> array delle chiavi che verrebbero cancellate
 *   OlismoReset.azzeraTutto()   -> cancella e ritorna conteggio
 *   OlismoReset.azzeraProfilo() -> solo profilo personale
 *   OlismoReset.azzeraMediazione() -> solo dossier mediazione
 *   OlismoReset.montaPulsante(opzioni) -> inserisce un bottone "Azzera dati"
 */
(function (global) {
  'use strict';

  // Prefissi che identificano dati Olismo
  var PREFIX_PROFILO = [
    'olismo_profile_',
    'olismo_profile_storico_',
    'olismo_prompt_',
    'olismo_'   // catch-all sicuro per il namespace
  ];
  var PREFIX_MEDIAZIONE = [
    'olismo_mediazione_'
  ];

  // Chiavi legacy di olismo-core.js (senza prefisso namespaced)
  var LEGACY_KEYS = [
    'quiz_enneagram_v1', 'quiz_enneagramma_v1', 'quiz_frutti_v1',
    'quiz_adattamenti_v1', 'quiz_egogramma_v1', 'quiz_carezze_v1',
    'quiz_copione_v1', 'quiz_transazioni_v1', 'quiz_matrice_v1',
    'quiz_chakra_v1', 'quiz_cristalli_v1', 'quiz_bach_v1', 'quiz_fes_v1',
    'quiz_bush_v1', 'quiz_diet_v1', 'quiz_vak_v1', 'quiz_violenza_v1',
    'quiz_psicoanalogica_v1', 'quiz_check_v1', 'quiz_empowerment_v1',
    'frutti_result', 'at_result', 'ego_result', 'vak_result',
    'check_result', 'trans_result', 'diet_result'
  ];
  var LEGACY_PREFIXES = ['quiz_', 'frutti_', 'at_result', 'ego_', 'vak_', 'check_', 'trans_', 'diet_'];

  function storageOk(s) {
    try { var t = '__olismo_reset_test__'; s.setItem(t,'1'); s.removeItem(t); return true; }
    catch (e) { return false; }
  }

  function _matchPrefix(key, prefixes) {
    for (var i = 0; i < prefixes.length; i++) {
      if (key.indexOf(prefixes[i]) === 0) return true;
    }
    return false;
  }

  function _raccogliChiavi(storage, includeProfilo, includeMediazione, includeLegacy) {
    if (!storageOk(storage)) return [];
    var trovate = [];
    for (var i = 0; i < storage.length; i++) {
      var k = storage.key(i);
      if (!k) continue;
      if (includeProfilo && _matchPrefix(k, PREFIX_PROFILO)) { trovate.push(k); continue; }
      if (includeMediazione && _matchPrefix(k, PREFIX_MEDIAZIONE)) { trovate.push(k); continue; }
      if (includeLegacy) {
        if (LEGACY_KEYS.indexOf(k) >= 0) { trovate.push(k); continue; }
        if (_matchPrefix(k, LEGACY_PREFIXES)) { trovate.push(k); continue; }
      }
    }
    return trovate;
  }

  function elencaChiavi() {
    var ls = _raccogliChiavi(global.localStorage, true, true, true);
    var ss = _raccogliChiavi(global.sessionStorage, true, true, true);
    return { localStorage: ls, sessionStorage: ss, totale: ls.length + ss.length };
  }

  function _esegui(includeProfilo, includeMediazione, includeLegacy) {
    var rimosse = 0;
    [global.localStorage, global.sessionStorage].forEach(function (s) {
      var keys = _raccogliChiavi(s, includeProfilo, includeMediazione, includeLegacy);
      keys.forEach(function (k) {
        try { s.removeItem(k); rimosse++; } catch (e) {}
      });
    });
    return rimosse;
  }

  function azzeraTutto() { return _esegui(true, true, true); }
  function azzeraProfilo() { return _esegui(true, false, true); }
  function azzeraMediazione() { return _esegui(false, true, false); }

  /**
   * Monta un pulsante "Azzera dati in cache" in fondo alla pagina o in un
   * container specifico. Mostra sempre una conferma esplicita prima di cancellare.
   *
   * opzioni:
   *   - container: selettore CSS dove inserire il bottone (default: nessuno = floating)
   *   - scope: 'tutto' | 'profilo' | 'mediazione' (default 'tutto')
   *   - testo: label del bottone
   *   - dopoReset: callback eseguita dopo l'azzeramento
   */
  function montaPulsante(opt) {
    opt = opt || {};
    var scope = opt.scope || 'tutto';
    var testo = opt.testo || '🗑️ Azzera dati in cache';
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = testo;
    btn.title = 'Cancella tutti i dati salvati localmente sul tuo browser per ricominciare da capo.';
    btn.style.cssText = (opt.style) || 'padding:.6rem 1rem;background:#fff;color:#9a3412;border:1px solid #fdba74;border-radius:8px;cursor:pointer;font-family:inherit;font-size:.85rem;font-weight:600;transition:all .2s';
    btn.onmouseover = function () { btn.style.background = '#fff7ed'; };
    btn.onmouseout = function () { btn.style.background = '#fff'; };
    btn.addEventListener('click', function () {
      var elenco = elencaChiavi();
      if (elenco.totale === 0) {
        alert('Nessun dato Olismo salvato sul browser. Niente da cancellare.');
        return;
      }
      var msg = '';
      if (scope === 'tutto') {
        msg = 'Confermi la cancellazione di TUTTI i dati Olismo salvati sul browser?\n\n' +
              '• ' + elenco.localStorage.length + ' chiavi in memoria persistente\n' +
              '• ' + elenco.sessionStorage.length + ' chiavi in memoria di sessione\n\n' +
              'Verranno cancellati: profilo personale, test compilati, dossier di mediazione, prompt salvati.\n\n' +
              'Operazione irreversibile. Procedo?';
      } else if (scope === 'profilo') {
        msg = 'Confermi la cancellazione del PROFILO PERSONALE (test, motori, prompt)?\n\nI dossier di mediazione restano intatti.\n\nProcedo?';
      } else if (scope === 'mediazione') {
        msg = 'Confermi la cancellazione di TUTTI i dossier di mediazione?\n\nIl profilo personale resta intatto.\n\nProcedo?';
      }
      if (!confirm(msg)) return;
      var rimosse;
      if (scope === 'profilo') rimosse = azzeraProfilo();
      else if (scope === 'mediazione') rimosse = azzeraMediazione();
      else rimosse = azzeraTutto();
      alert('Cancellate ' + rimosse + ' chiavi. Adesso puoi ricominciare con un nuovo profilo o un nuovo dossier.');
      if (typeof opt.dopoReset === 'function') {
        try { opt.dopoReset(rimosse); } catch (e) {}
      } else {
        // di default ricarica la pagina così tutti gli stati in-memory si resettano
        location.reload();
      }
    });

    if (opt.container) {
      var host = document.querySelector(opt.container);
      if (host) host.appendChild(btn);
    } else {
      // floating in basso a destra
      btn.style.position = 'fixed';
      btn.style.bottom = '16px';
      btn.style.right = '16px';
      btn.style.zIndex = '9998';
      btn.style.boxShadow = '0 4px 12px rgba(0,0,0,.12)';
      document.body.appendChild(btn);
    }
    return btn;
  }

  global.OlismoReset = {
    elencaChiavi: elencaChiavi,
    azzeraTutto: azzeraTutto,
    azzeraProfilo: azzeraProfilo,
    azzeraMediazione: azzeraMediazione,
    montaPulsante: montaPulsante
  };
})(window);

