*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Outfit',sans-serif;background:#f9f5ef;color:#2a2520;overflow-x:hidden;font-size:16px}

/* ── VARIABLES ── */
:root{
  --ivory:#f9f5ef;--ivory2:#f3ede3;--ivory3:#ece4d8;--ivory4:#e2d8cc;
  --ink:#2a2520;--ink2:#4a4540;--ink3:#7a7268;--ink4:#a89e92;
  --gold:#b8935a;--gold2:#d4a96a;--gold3:#e8c990;--gold-pale:#f5ecd8;
  --sage:#5a7a6a;--sage2:#7a9a88;--sage3:#c8dcd0;
  --dusty:#8a6a7a;--dusty2:#b49aaa;--dusty3:#e8d8e0;
  --slate:#3a4a5a;--slate2:#5a6a7a;--slate3:#d0d8e0;
  --border:rgba(184,147,90,.2);--border2:rgba(184,147,90,.38);
  --shadow:0 2px 20px rgba(42,37,32,.07);
  --shadow2:0 8px 48px rgba(42,37,32,.12);
  --r:8px;--rl:14px;--rxl:22px;
}

::-webkit-scrollbar{width:5px}
::-webkit-scrollbar-track{background:var(--ivory2)}
::-webkit-scrollbar-thumb{background:var(--gold);border-radius:3px}

/* ── HEADER ── */
header{
  position:fixed;top:0;left:0;right:0;z-index:200;
  background:rgba(249,245,239,.93);backdrop-filter:blur(14px);
  border-bottom:1px solid var(--border);
  display:flex;align-items:center;justify-content:space-between;
  padding:0 2.5rem;height:68px;
  transition:box-shadow .3s;
}
header.scrolled{box-shadow:0 4px 32px rgba(42,37,32,.1)}
.logo{
  font-family:'Cormorant Garamond',serif;font-size:1.35rem;font-weight:400;
  letter-spacing:.1em;color:var(--ink);text-decoration:none;
  display:flex;align-items:center;gap:.75rem;
}
.logo-mark{
  width:32px;height:32px;border-radius:50%;
  border:1.5px solid var(--gold);
  display:flex;align-items:center;justify-content:center;
  font-size:.9rem;color:var(--gold);
}
.logo span{color:var(--gold)}
nav{display:flex;align-items:center;gap:.1rem}
.nav-link{
  padding:.4rem .85rem;border-radius:4px;
  font-size:.78rem;font-weight:400;letter-spacing:.08em;text-transform:uppercase;
  color:var(--ink3);text-decoration:none;
  transition:color .2s,background .2s;cursor:pointer;border:none;background:transparent;
}
.nav-link:hover,.nav-link.active{color:var(--gold);background:rgba(184,147,90,.07)}
.search-btn{
  margin-left:.5rem;padding:.5rem .95rem;
  border:1px solid var(--border2);border-radius:20px;
  background:transparent;color:var(--ink3);cursor:pointer;
  font-size:.78rem;letter-spacing:.06em;font-family:'Outfit',sans-serif;
  transition:all .2s;display:flex;align-items:center;gap:.4rem;
}
.search-btn:hover{border-color:var(--gold);color:var(--gold);background:var(--gold-pale)}
.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:.5rem;background:transparent;border:none}
.hamburger span{width:22px;height:1.5px;background:var(--ink3);transition:.3s}

/* ── HERO ── */
#hero{
  display:flex;flex-direction:column;
  align-items:center;justify-content:center;
  text-align:center;padding:8rem 2rem 7rem;
  position:relative;overflow:hidden;
  background:var(--ivory);
  --hero-photo: url('data:image/jpeg;base64,');
}
#hero.has-photo{
  background-image:var(--hero-photo);
  background-size:cover;
  background-position:center 35%;
}
#hero.has-photo .hero-overlay{display:block}
#hero.has-photo .pill{background:rgba(0,0,0,.32);color:#fff;border-color:rgba(255,255,255,.5);text-shadow:0 1px 4px rgba(0,0,0,.4)}
#hero.has-photo .pill:hover{background:rgba(0,0,0,.48);border-color:rgba(255,255,255,.75)}
#hero.has-photo .hero-title{color:#fff;text-shadow:0 2px 18px rgba(0,0,0,.45)}
#hero.has-photo .hero-title em{color:var(--gold)}
#hero.has-photo .hero-sub,#hero.has-photo .hero-subtitle{color:rgba(255,255,255,.95)!important;text-shadow:0 1px 16px rgba(0,0,0,.75),0 0 30px rgba(0,0,0,.4)!important;font-weight:400}
#hero.has-photo .hero-subtitle{color:rgba(255,255,255,.92);text-shadow:0 1px 14px rgba(0,0,0,.55)}
#hero.has-photo .hero-eyebrow{color:rgba(255,220,120,.9)}
#hero.has-photo .hero-badge{background:rgba(255,255,255,.12);color:#fff;border-color:rgba(255,255,255,.3)}
#hero.has-photo .hero-cta-secondary,#hero.has-photo .btn-ghost{
  color:#fff!important;
  border:2px solid rgba(255,255,255,.85)!important;
  background:rgba(0,0,0,.35)!important;
  text-shadow:0 1px 6px rgba(0,0,0,.6)!important;
  font-weight:500!important;
}
#hero.has-photo .hero-disclaimer{color:rgba(255,255,255,.55)}
.hero-overlay{
  display:none;
  position:absolute;inset:0;z-index:0;
  background:rgba(18,12,8,.42);
}
.hero-bg-circle{
  position:absolute;border-radius:50%;
  background:radial-gradient(circle,rgba(184,147,90,.08) 0%,transparent 70%);
}
.hbc1{width:700px;height:700px;top:50%;left:50%;transform:translate(-50%,-50%)}
.hbc2{width:400px;height:400px;top:10%;right:-100px;background:radial-gradient(circle,rgba(90,122,106,.06) 0%,transparent 70%)}
.hbc3{width:300px;height:300px;bottom:10%;left:-80px;background:radial-gradient(circle,rgba(138,106,122,.06) 0%,transparent 70%)}
.sacred-ring{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:480px;height:480px;border-radius:50%;
  border:1px solid rgba(184,147,90,.12);pointer-events:none;
}
.sacred-ring2{width:320px;height:320px;border:1px solid rgba(184,147,90,.08)}
.sacred-ring3{width:160px;height:160px;border:1px solid rgba(184,147,90,.15)}
.hero-eyebrow{
  position:relative;
  font-size:.72rem;letter-spacing:.4em;text-transform:uppercase;
  color:var(--gold);margin-bottom:1.75rem;
  display:flex;align-items:center;gap:1rem;
}
.hero-eyebrow::before,.hero-eyebrow::after{content:'';display:block;width:50px;height:1px;background:var(--gold3)}
h1.hero-title{
  position:relative;
  font-family:'Cormorant Garamond',serif;
  font-size:clamp(3rem,7.5vw,5.8rem);font-weight:300;line-height:1.08;
  color:var(--ink);margin-bottom:1.5rem;letter-spacing:-.01em;
}
h1.hero-title em{color:var(--gold);font-style:italic}
.hero-sub{
  position:relative;
  font-size:1.05rem;font-weight:300;color:var(--ink3);
  line-height:1.85;max-width:580px;margin:0 auto 3rem;
}
.hero-pills{
  position:relative;
  display:flex;flex-wrap:wrap;gap:.6rem;justify-content:center;margin-bottom:3.5rem;
}
.pill{
  padding:.42rem 1.15rem;border:1px solid var(--border2);border-radius:20px;
  font-size:.8rem;color:var(--ink3);cursor:pointer;
  transition:all .2s;background:rgba(249,245,239,.7);
}
.pill:hover{border-color:var(--gold);color:var(--gold);background:var(--gold-pale)}
.pill-cta{border-color:var(--gold)!important;background:rgba(184,147,90,.22)!important;color:#fff!important}
.pill-cta:hover{background:rgba(184,147,90,.4)!important}
.pill-dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:.4rem;vertical-align:middle}
.cta-row{position:relative;display:flex;gap:1rem;justify-content:center;flex-wrap:wrap}
.btn-gold{
  padding:.78rem 2.2rem;
  background:var(--gold);color:#fff;
  font-weight:500;font-size:.85rem;letter-spacing:.1em;text-transform:uppercase;
  border:none;border-radius:var(--r);cursor:pointer;
  transition:background .2s,transform .15s;font-family:'Outfit',sans-serif;
}
.btn-gold:hover{background:#a07840;transform:translateY(-1px)}
.btn-ghost{
  padding:.78rem 2.2rem;background:transparent;
  border:1.5px solid var(--border2);color:var(--ink2);
  font-weight:400;font-size:.85rem;letter-spacing:.1em;text-transform:uppercase;
  border-radius:var(--r);cursor:pointer;transition:all .2s;font-family:'Outfit',sans-serif;
}
.btn-ghost:hover{border-color:var(--gold);color:var(--gold);background:var(--gold-pale)}
.scroll-hint{
  position:absolute;bottom:2.5rem;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:.6rem;
  color:var(--ink4);font-size:.7rem;letter-spacing:.25em;text-transform:uppercase;
  animation:float 2.8s ease-in-out infinite;
}
.scroll-hint::after{content:'';display:block;width:1px;height:44px;background:linear-gradient(to bottom,var(--gold),transparent)}
@keyframes float{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(-7px)}}

/* ── SECTION COMMON ── */
section{padding:6rem 0}
.container{max-width:1180px;margin:0 auto;padding:0 2rem}
.sec-hd{text-align:center;margin-bottom:4rem}
.sec-eye{font-size:.7rem;letter-spacing:.38em;text-transform:uppercase;color:var(--gold);margin-bottom:.9rem}
.sec-title{
  font-family:'Cormorant Garamond',serif;
  font-size:clamp(2rem,4vw,3.1rem);font-weight:300;
  color:var(--ink);line-height:1.18;
}
.sec-title em{color:var(--gold);font-style:italic}
.sec-div{width:56px;height:1px;background:var(--gold3);margin:1.4rem auto 1.6rem}
.sec-desc{font-size:.92rem;font-weight:300;color:var(--ink3);line-height:1.9;max-width:600px;margin:0 auto}

/* ── SEARCH OVERLAY ── */
#search-overlay{
  position:fixed;inset:0;z-index:300;
  background:rgba(249,245,239,.97);backdrop-filter:blur(16px);
  display:none;flex-direction:column;align-items:center;padding-top:14vh;
}
#search-overlay.open{display:flex}
.s-close{
  position:absolute;top:1.5rem;right:1.5rem;
  background:transparent;border:1px solid var(--border2);
  color:var(--ink3);width:40px;height:40px;border-radius:50%;
  cursor:pointer;font-size:1rem;transition:all .2s;
  display:flex;align-items:center;justify-content:center;
}
.s-close:hover{border-color:var(--gold);color:var(--gold)}
.s-inner{width:100%;max-width:700px;padding:0 1.5rem}
.s-label{
  font-family:'Cormorant Garamond',serif;font-size:1.5rem;
  font-weight:300;font-style:italic;color:var(--ink3);
  margin-bottom:1.5rem;display:block;
}
.s-wrap{position:relative;margin-bottom:1.75rem}
.s-wrap input{
  width:100%;padding:1rem 1.5rem 1rem 3.5rem;
  background:white;border:1.5px solid var(--border2);border-radius:var(--rl);
  font-family:'Outfit',sans-serif;font-size:1rem;font-weight:300;color:var(--ink);
  outline:none;transition:border-color .2s;
  box-shadow:var(--shadow);
}
.s-wrap input:focus{border-color:var(--gold)}
.s-wrap input::placeholder{color:var(--ink4)}
.s-icon{position:absolute;left:1.1rem;top:50%;transform:translateY(-50%);color:var(--gold);font-size:1.1rem}
#s-list{max-height:56vh;overflow-y:auto}
.s-cat-lbl{
  font-size:.68rem;letter-spacing:.3em;text-transform:uppercase;
  color:var(--gold);padding:.85rem 0 .4rem;
  border-bottom:1px solid var(--border);margin-bottom:.35rem;
}
.s-item{
  display:flex;align-items:center;gap:1rem;
  padding:.75rem .9rem;border-radius:var(--r);
  cursor:pointer;transition:background .15s;
}
.s-item:hover{background:var(--ivory2)}
.s-dot{width:9px;height:9px;border-radius:50%;flex-shrink:0}
.s-name{font-size:.92rem;font-weight:400;color:var(--ink)}
.s-meta{font-size:.78rem;color:var(--ink3)}

/* ── EXPLORER ── */
#explorer{background:white}
.exp-tabs{
  display:flex;gap:.3rem;flex-wrap:wrap;
  border-bottom:1.5px solid var(--ivory3);margin-bottom:2.5rem;padding-bottom:1.25rem;
}
.exp-tab{
  padding:.55rem 1.3rem;border-radius:4px;
  font-size:.78rem;letter-spacing:.09em;text-transform:uppercase;
  color:var(--ink3);background:transparent;border:none;cursor:pointer;
  transition:all .2s;position:relative;
}
.exp-tab.active{color:var(--gold)}
.exp-tab.active::after{
  content:'';position:absolute;bottom:-1.4rem;left:0;right:0;
  height:2px;background:var(--gold);border-radius:1px;
}
.exp-tab:hover:not(.active){color:var(--ink)}
.exp-body{display:grid;grid-template-columns:290px 1fr;gap:2rem;align-items:start}
@media(max-width:820px){.exp-body{grid-template-columns:1fr}}
.exp-list{display:flex;flex-direction:column;gap:.45rem;max-height:72vh;overflow-y:auto;padding-right:.5rem}
.exp-card{
  padding:.85rem 1.05rem;border:1.5px solid var(--ivory3);
