/* ══ DIET RESULT ══ */
.diet-result{display:none;margin-top:2rem;border:1.5px solid var(--border);border-radius:var(--rxl);overflow:hidden;background:white}
.diet-res-header{background:linear-gradient(135deg,var(--gold),var(--gold2));padding:1.5rem 2rem;color:white}
.diet-res-title{font-family:'Cormorant Garamond',serif;font-size:1.3rem;font-weight:300;margin-bottom:.25rem}
.diet-res-sub{font-size:.78rem;opacity:.85}
.diet-res-section{padding:1.2rem 2rem;border-bottom:1px solid var(--ivory3)}
.diet-res-section:last-child{border-bottom:none}
.diet-res-section h4{font-size:.82rem;font-weight:700;color:var(--ink);letter-spacing:.06em;text-transform:uppercase;margin-bottom:.7rem}
.diet-res-section p{font-size:.85rem;color:var(--ink2);line-height:1.75}
.diet-chakra-note{font-size:.78rem;color:var(--gold)!important;margin-top:.5rem;font-style:italic}
.diet-food-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:.65rem}
.diet-food-card{background:var(--ivory2);border-radius:8px;padding:.75rem 1rem}
.diet-food-cat{font-size:.72rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;margin-bottom:.25rem}
.diet-food-val{font-size:.8rem;color:var(--ink2);line-height:1.5}
.diet-adatt-note{background:rgba(184,147,90,.08);padding:.7rem 1rem;border-radius:6px;border-left:3px solid var(--gold);font-size:.83rem!important}
.diet-week-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;margin-top:.5rem}
.diet-week-scroll::-webkit-scrollbar{height:4px}
.diet-week-scroll::-webkit-scrollbar-track{background:var(--ivory3)}
.diet-week-scroll::-webkit-scrollbar-thumb{background:var(--gold);border-radius:2px}
.diet-table{width:100%;border-collapse:collapse;min-width:780px;font-size:.78rem}
.diet-table th{
  background:var(--gold);color:white;
  padding:.5rem .6rem;text-align:center;font-weight:600;
  font-size:.72rem;letter-spacing:.05em;white-space:nowrap;
}
.diet-table th.dt-meal-head{
  background:var(--ivory3);color:var(--ink3);font-size:.68rem;
  font-weight:700;text-transform:uppercase;letter-spacing:.08em;
  text-align:left;width:70px;
}
.diet-table td{
  padding:.45rem .6rem;border:1px solid var(--ivory3);
  vertical-align:top;font-size:.75rem;color:var(--ink2);line-height:1.5;
}
.diet-table td:first-child{
  background:var(--ivory2);font-weight:600;font-size:.7rem;
  color:var(--gold);white-space:nowrap;
}
.diet-table tr:hover td{background:var(--ivory2)}
.diet-table tr:hover td:first-child{background:var(--ivory3)}
.diet-bottom-row{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
@media(max-width:640px){.diet-bottom-row{grid-template-columns:1fr}}
.diet-extra-card{background:var(--gold-pale);border-radius:8px;padding:.9rem}
.diet-extra-label{font-size:.7rem;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:.08em;margin-bottom:.3rem}
.diet-extra-val{font-size:.8rem;color:var(--ink2);line-height:1.5}
.diet-disclaimer{padding:.8rem 2rem;font-size:.7rem;color:var(--ink4);text-align:center;border-top:1px solid var(--ivory3)}

.diet-week-scroll::-webkit-scrollbar{height:4px}
.diet-week-scroll::-webkit-scrollbar-track{background:var(--ivory3);border-radius:2px}
.diet-week-scroll::-webkit-scrollbar-thumb{background:var(--gold);border-radius:2px}

.nav-sep{color:var(--border2);font-size:.9rem;padding:0 .1rem;user-select:none;pointer-events:none}

/* ── MSG RATING ── */
.msg-rating{display:inline-flex;align-items:center;gap:.25rem;margin-left:.5rem}
.msg-rating button{
  background:none;border:none;cursor:pointer;font-size:.8rem;
  opacity:.4;padding:0;transition:all .15s;line-height:1;
}
.msg-rating button:hover{opacity:1;transform:scale(1.2)}
/* ── CLEAR CHAT BTN ── */
.chat-clear-btn{
  background:none;border:none;cursor:pointer;font-size:.72rem;
  color:var(--ink4);padding:.3rem .6rem;border-radius:12px;
  transition:all .15s;
}
.chat-clear-btn:hover{color:var(--dusty);background:var(--ivory3)}

/* ══ DARK MODE ══ */
body.dark{
  --ivory:#1a1612;--ivory2:#221e1a;--ivory3:#2e2a26;--ivory4:#3a3632;
  --ink:#f0ebe3;--ink2:#d0c8be;--ink3:#a09488;--ink4:#706860;
  --gold:#d4a96a;--gold2:#e8c070;--gold3:#f0d080;--gold-pale:rgba(184,147,90,.15);
  --border:rgba(184,147,90,.18);--border2:rgba(184,147,90,.32);
  --shadow:0 2px 20px rgba(0,0,0,.3);--shadow2:0 8px 48px rgba(0,0,0,.5);
}
body.dark header{background:rgba(26,22,18,.95)}
body.dark .chat-wrap{background:#221e1a}
body.dark .msg-bubble.ai{background:#2e2a26;color:var(--ink2)}
body.dark .msg-bubble.user{background:rgba(184,147,90,.2)}
body.dark .vak-test-wrap,
body.dark .check-test-wrap,
body.dark .diet-engine,
body.dark .compat-result,
body.dark .ego-test-section{background:#221e1a}
body.dark .site-card,body.dark .chisono-card{background:#221e1a;border-color:var(--border)}
body.dark .flower-mini-card,body.dark .bach-card{background:#221e1a}
body.dark .privacy-inner{background:#221e1a;color:var(--ink)}
body.dark #cookie-banner{background:rgba(10,8,6,.97)}
body.dark .ai-table th{background:#3a3632}
/* dark mode toggle button */
.dark-toggle{
  position:fixed;bottom:1.5rem;left:1.5rem;z-index:400;
  width:40px;height:40px;border-radius:50%;
  background:var(--ivory3);border:1.5px solid var(--border2);
  cursor:pointer;font-size:1rem;display:flex;align-items:center;justify-content:center;
  box-shadow:var(--shadow);transition:all .2s;
}
.dark-toggle:hover{transform:scale(1.1)}
body.dark .dark-toggle{background:#3a3632}

/* ══ CRISTALLI ══ */
#cristalli{background:var(--ivory)}
.cristalli-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(200px,1fr));
  gap:1rem;margin-top:2rem;
}
.cristallo-card{
  background:white;border-radius:var(--r);border:1.5px solid var(--border);
  padding:1.2rem;cursor:pointer;transition:all .2s;position:relative;overflow:hidden;
}
.cristallo-card:hover{transform:translateY(-3px);box-shadow:var(--shadow2)}
.cristallo-dot{
  width:44px;height:44px;border-radius:50%;margin:0 auto .75rem;
  display:flex;align-items:center;justify-content:center;
  font-size:1.3rem;
}
.cristallo-name{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:400;color:var(--ink);text-align:center;margin-bottom:.3rem}
.cristallo-funzione{font-size:.72rem;color:var(--ink3);text-align:center;line-height:1.45}
.cristallo-chakra{
  position:absolute;top:.5rem;right:.5rem;
  font-size:.6rem;font-weight:700;padding:.15rem .4rem;
  border-radius:8px;background:var(--ivory2);color:var(--ink4);
}
.cristalli-filter{display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:1.5rem;justify-content:center}
.cr-filter-btn{
  padding:.3rem .85rem;border-radius:20px;font-size:.72rem;font-weight:500;
  background:var(--ivory2);border:1.5px solid var(--border);color:var(--ink3);
  cursor:pointer;transition:all .15s;
}
.cr-filter-btn.active,.cr-filter-btn:hover{background:var(--gold);color:white;border-color:var(--gold)}
.cristallo-card.dim{opacity:.3;pointer-events:none}

/* ══ MEDITAZIONE ══ */
#meditazione{background:var(--ivory2)}
.medit-intro{max-width:720px;margin:0 auto 2.5rem;text-align:center;font-size:.9rem;color:var(--ink2);line-height:1.85}
.medit-tabs{display:flex;gap:.4rem;flex-wrap:wrap;justify-content:center;margin-bottom:2rem}
.medit-tab{
  padding:.4rem 1.1rem;border-radius:20px;font-size:.78rem;font-weight:500;
  border:1.5px solid var(--border);background:white;color:var(--ink3);cursor:pointer;transition:all .15s;
}
.medit-tab.active,.medit-tab:hover{background:var(--gold);color:white;border-color:var(--gold)}
.medit-content{display:none}
.medit-content.show{display:block}
.medit-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:1.2rem}
.medit-card{
  background:white;border-radius:var(--r);border:1.5px solid var(--border);
  padding:1.5rem;position:relative;overflow:hidden;
}
.medit-card::before{
  content:'';position:absolute;top:0;left:0;right:0;height:3px;
  background:var(--card-color, var(--gold));
}
.medit-card-icon{font-size:2rem;margin-bottom:.6rem}
.medit-card-title{font-family:'Cormorant Garamond',serif;font-size:1.1rem;font-weight:400;color:var(--ink);margin-bottom:.3rem}
.medit-card-tag{font-size:.68rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink4);margin-bottom:.6rem}
.medit-card-desc{font-size:.82rem;color:var(--ink2);line-height:1.75;margin-bottom:.8rem}
.medit-card-steps{list-style:none;padding:0}
.medit-card-steps li{font-size:.78rem;color:var(--ink2);padding:.25rem 0;border-bottom:1px solid var(--ivory3);display:flex;gap:.5rem}
.medit-card-steps li:last-child{border-bottom:none}
.medit-card-steps li::before{content:'→';color:var(--gold);flex-shrink:0}
.medit-timer{
  display:inline-flex;align-items:center;gap:.4rem;margin-top:.8rem;
  font-size:.72rem;color:var(--gold);font-weight:500;padding:.3rem .7rem;
  background:var(--gold-pale);border-radius:12px;
}

/* ══ MOB MENU FIX ══ */
#mob-menu{
  display:none;position:fixed;top:68px;left:0;right:0;z-index:190;
  background:var(--ivory);border-bottom:1px solid var(--border);
  padding:1rem;max-height:calc(100vh - 68px);overflow-y:auto;
  flex-direction:column;gap:.2rem;
}
#mob-menu.open{display:flex}
#mob-menu .nav-link{padding:.75rem 1rem;border-radius:8px;font-size:.88rem;text-align:left;width:100%}
.hamburger.active span:nth-child(1){transform:translateY(7px) rotate(45deg)}
.hamburger.active span:nth-child(2){opacity:0}
.hamburger.active span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}

/* ══ AT CARD ENGINE ══ */
.at-section-title{
  font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;
  color:var(--ac,var(--gold));margin:.9rem 0 .35rem;padding-top:.7rem;
  border-top:1px solid var(--ivory3);
}
.at-giochi{display:flex;flex-direction:column;gap:.4rem;margin-bottom:.3rem}
.at-gioco{
  display:flex;gap:.5rem;font-size:.78rem;color:var(--ink2);line-height:1.55;
  background:var(--ivory2);border-radius:6px;padding:.45rem .6rem;
}
.at-gioco-icon{color:var(--ac,var(--gold));flex-shrink:0;font-size:.85rem}
.at-copione-vita{
  font-size:.8rem;color:var(--ink2);line-height:1.65;
  border-left:3px solid var(--ac,var(--gold));padding:.4rem .7rem;
  background:rgba(184,147,90,.06);border-radius:0 6px 6px 0;
}
.at-credenza{
  display:flex;gap:.5rem;align-items:flex-start;margin:.5rem 0;
  font-size:.78rem;color:var(--ink3);font-style:italic;line-height:1.6;
  background:var(--ivory2);border-radius:6px;padding:.5rem .7rem;
}
.at-credenza-icon{flex-shrink:0;font-size:.9rem}
.at-permesso{
  display:flex;gap:.5rem;align-items:flex-start;
  font-size:.78rem;color:var(--sage);line-height:1.6;
  background:rgba(90,122,106,.08);border-radius:6px;padding:.5rem .7rem;
  border:1px solid rgba(90,122,106,.2);margin:.4rem 0;
}
.at-permesso-icon{flex-shrink:0;color:var(--gold);font-size:.9rem}

/* ══ SEZIONE TRANSAZIONI ══ */
#transazioni{background:linear-gradient(135deg,var(--ivory) 0%,#f0e8da 100%)}
.trans-regole{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-bottom:2rem}
@media(max-width:768px){.trans-regole{grid-template-columns:1fr}}
.trans-regola{
  display:flex;gap:1rem;align-items:flex-start;
  background:white;border-radius:10px;padding:1.1rem 1.2rem;
  border:1px solid var(--border);
}
.trans-num{
  flex-shrink:0;width:32px;height:32px;border-radius:50%;
  background:var(--gold);color:white;font-weight:700;font-size:.95rem;
  display:flex;align-items:center;justify-content:center;
}
.trans-r-title{font-weight:600;font-size:.85rem;color:var(--ink1);margin-bottom:.3rem}
.trans-r-desc{font-size:.78rem;color:var(--ink3);line-height:1.6;margin:0}
.trans-sub-title{font-size:1rem;font-weight:600;color:var(--ink1);margin:1.5rem 0 .6rem}
.trans-header-row{margin-bottom:.5rem}

/* TRANS CARDS */
.trans-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:1rem;margin-bottom:2.5rem}
.trans-card{
  background:white;border-radius:10px;border:1px solid var(--border);
  overflow:hidden;transition:box-shadow .2s;
}
.trans-card:hover{box-shadow:var(--shadow-md)}
.trans-card-header{
  padding:.75rem 1rem;cursor:pointer;
  display:flex;align-items:center;justify-content:space-between;gap:.6rem;
  border-bottom:1px solid var(--ivory3);
}
.trans-card-header:hover{background:var(--ivory2)}
.trans-adatt-label{font-weight:700;font-size:.85rem;color:var(--ink1)}
.trans-vettore-tag{
  font-size:.7rem;background:var(--ivory3);color:var(--ink3);
  padding:.2rem .5rem;border-radius:12px;white-space:nowrap;
}
.trans-chevron{font-size:.75rem;color:var(--ink4);transition:transform .2s}
.trans-card.open .trans-chevron{transform:rotate(180deg)}
.trans-card-body{display:none;padding:1rem}
.trans-card.open .trans-card-body{display:block}
.trans-body-section{margin-bottom:.9rem}
.trans-bs-title{font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.09em;color:var(--gold);margin-bottom:.35rem}
.trans-incrociata{
  background:var(--ivory2);border-radius:6px;padding:.6rem .8rem;
  font-size:.78rem;color:var(--ink2);line-height:1.6;
  border-left:3px solid #e57373;margin-bottom:.4rem;
}
.trans-racket{
  background:rgba(184,147,90,.08);border-radius:6px;padding:.5rem .8rem;
  font-size:.78rem;color:var(--ink2);line-height:1.6;font-style:italic;
}
.trans-rimedi{display:flex;flex-direction:column;gap:.4rem}
.trans-rimedio{
  display:flex;gap:.5rem;align-items:flex-start;
  font-size:.76rem;color:var(--ink2);line-height:1.55;
}
.trans-rimedio-icon{flex-shrink:0;font-size:.9rem;margin-top:.05rem}
.trans-gioco{
  font-size:.77rem;color:var(--ink2);line-height:1.6;
  padding:.35rem .6rem;background:var(--ivory2);border-radius:6px;margin-bottom:.3rem;
}

/* VETTORI GRID */
.vettori-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:.6rem;margin-top:.5rem}
.vettore-card{
  background:white;border-radius:8px;padding:.65rem .9rem;
  font-size:.76rem;color:var(--ink2);line-height:1.55;
  border:1px solid var(--border);
}
.vc-label{font-weight:700;font-size:.8rem;margin-bottom:.2rem}
.v-gn .vc-label{color:#ef4444}
.v-gn-neg .vc-label{color:#b91c1c}
.v-ga .vc-label{color:#f59e0b}
.v-ga-neg .vc-label{color:#b45309}
.v-a .vc-label{color:#3b82f6}
.v-bl .vc-label{color:#10b981}
.v-bl-neg .vc-label{color:#059669}
.v-ba .vc-label{color:#8b5cf6}
.v-ba-neg .vc-label{color:#6d28d9}

/* ══ GUIDA PERCORSI — Redesign ══ */
.guida-percorsi{margin-top:2rem}
.guida-percorsi>h3{
  font-family:'Cormorant Garamond',serif;
  font-size:1.55rem;font-weight:600;color:var(--ink1);
  margin-bottom:1.5rem;
}
.guida-percorsi>h3 em{color:var(--gold);font-style:italic}
.percorsi-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:1.25rem;
}
@media(max-width:900px){.percorsi-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.percorsi-grid{grid-template-columns:1fr}}

.percorso-card{
  border-radius:12px;
  background:white;
  border:1px solid var(--border);
  overflow:hidden;
  display:flex;flex-direction:column;
  transition:transform .2s, box-shadow .2s;
}
.percorso-card:hover{
  transform:translateY(-3px);
  box-shadow:0 8px 28px rgba(0,0,0,.1);
}

/* Top accent bar */
.percorso-accent{height:4px;width:100%}

/* Card content */
.percorso-inner{padding:1.3rem 1.4rem 1.4rem;flex:1;display:flex;flex-direction:column;gap:.9rem}

/* Icon + Badge row */
.percorso-meta{display:flex;align-items:center;gap:.75rem}
.percorso-badge{
  width:38px;height:38px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:1.5rem;flex-shrink:0;
}
.percorso-num{
  font-family:'Cormorant Garamond',serif;
  font-size:.7rem;font-weight:700;letter-spacing:.12em;
  text-transform:uppercase;color:var(--ink4);
}

/* Title & audience */
.percorso-title-new{
  font-size:.95rem;font-weight:700;color:var(--ink1);
  line-height:1.3;margin:0 0 .2rem;
}
.percorso-tag{
  display:inline-flex;align-items:center;gap:.3rem;
  font-size:.68rem;color:var(--ink3);line-height:1.4;
  background:var(--ivory2);border-radius:20px;
  padding:.18rem .6rem;
}

/* Steps list */
.percorso-steps-new{
  display:flex;flex-direction:column;gap:.5rem;
  flex:1;
}
.ps-new{
  display:flex;align-items:baseline;gap:.55rem;
  font-size:.78rem;color:var(--ink2);line-height:1.55;
  padding:.35rem 0;
  border-bottom:1px solid var(--ivory3);
}
.ps-new:last-child{border-bottom:none}
.ps-new-n{
  flex-shrink:0;
  width:18px;height:18px;border-radius:50%;
  font-size:.62rem;font-weight:700;
  display:inline-flex;align-items:center;justify-content:center;
  color:white;margin-top:.1rem;
}

/* CTA button */
.percorso-cta{
  margin-top:auto;padding-top:.9rem;
}
.percorso-btn{
  width:100%;padding:.45rem;
  font-size:.72rem;font-weight:600;
  border-radius:6px;border:none;cursor:pointer;
  text-transform:uppercase;letter-spacing:.06em;
  opacity:.85;transition:opacity .2s;
}
.percorso-btn:hover{opacity:1}

/* ══ DIAGRAMMA VIAGGIO ══ */
#percorso-viaggio{
  background:linear-gradient(180deg,var(--ivory) 0%,white 100%);
  padding:3rem 0 2rem;
}
.viaggio-title{
  text-align:center;margin-bottom:2.5rem;
}
.viaggio-title h2{
  font-family:'Cormorant Garamond',serif;
  font-size:2rem;font-weight:600;color:var(--ink1);
  margin:0 0 .4rem;
}
.viaggio-title h2 em{color:var(--gold);font-style:italic}
.viaggio-title p{font-size:.9rem;color:var(--ink3);margin:0}

/* Timeline orizzontale */
.viaggio-timeline{
  display:flex;align-items:stretch;
  gap:0;margin-bottom:2rem;
  overflow-x:auto;padding-bottom:.5rem;
}
.viaggio-timeline::-webkit-scrollbar{height:3px}
.viaggio-timeline::-webkit-scrollbar-thumb{background:var(--gold);border-radius:2px}

.viaggio-fase{
  flex:1;min-width:160px;
  display:flex;flex-direction:column;align-items:center;
  position:relative;cursor:pointer;
  padding:1.25rem .8rem 1rem;
  border-radius:0;
  transition:background .2s;
}
.viaggio-fase:hover{background:var(--ivory2)}
.viaggio-fase:first-child{border-radius:12px 0 0 12px}
.viaggio-fase:last-child{border-radius:0 12px 12px 0}

/* Connector arrow between phases */
.viaggio-fase:not(:last-child)::after{
  content:'';
  position:absolute;right:-1px;top:50%;
  width:2px;height:40%;
  transform:translateY(-50%);
  background:var(--ivory3);
}

.viaggio-fase-num{
  width:32px;height:32px;border-radius:50%;
  font-size:.75rem;font-weight:700;
  display:flex;align-items:center;justify-content:center;
  color:white;margin-bottom:.5rem;flex-shrink:0;
}
.viaggio-fase-icon{font-size:1.6rem;margin-bottom:.4rem;line-height:1}
.viaggio-fase-label{
  font-size:.7rem;font-weight:700;text-transform:uppercase;
  letter-spacing:.08em;color:var(--ink4);
  margin-bottom:.25rem;text-align:center;
}
.viaggio-fase-title{
  font-size:.88rem;font-weight:600;color:var(--ink1);
  text-align:center;line-height:1.3;margin-bottom:.4rem;
}
.viaggio-fase-tools{
  display:flex;flex-wrap:wrap;gap:.25rem;justify-content:center;
}
.viaggio-tool{
  font-size:.62rem;background:var(--ivory3);
  color:var(--ink3);padding:.1rem .4rem;
  border-radius:10px;white-space:nowrap;
}

/* Arrow between phases */
.viaggio-arrow{
  display:flex;align-items:center;
  color:var(--gold);font-size:1.2rem;
  flex-shrink:0;padding:0 .1rem;
  align-self:center;margin-top:-1rem;
}

/* Bottom CTA strip */
.viaggio-cta-strip{
  display:flex;justify-content:center;
  gap:.75rem;flex-wrap:wrap;margin-top:1.5rem;
}
.viaggio-btn{
  padding:.55rem 1.4rem;border-radius:20px;
  font-size:.78rem;font-weight:600;cursor:pointer;
  border:1.5px solid var(--gold);
  background:transparent;color:var(--gold);
  transition:all .2s;
}
.viaggio-btn:hover,.viaggio-btn.active{
  background:var(--gold);color:white;
}
.viaggio-btn.primary{
  background:var(--gold);color:white;
}

/* ══ TEST VETTORE COMUNICATIVO ══ */
.trans-test-container{
  background:white;border-radius:14px;
  border:1px solid var(--border);
  padding:2rem;margin-bottom:3rem;
  box-shadow:0 2px 20px rgba(0,0,0,.04);
}
.trans-welcome-box{text-align:center;padding:.5rem 0 1rem}
.trans-welcome-grid{
  display:flex;justify-content:center;gap:2rem;
  margin-bottom:1.5rem;flex-wrap:wrap;
}
.trans-welcome-item{display:flex;align-items:center;gap:.6rem}
.trans-welcome-icon{font-size:1.4rem}
.trans-welcome-text{font-size:.82rem;color:var(--ink2);text-align:left;line-height:1.45}
.trans-start-btn{
  padding:.7rem 2.4rem;background:var(--gold);color:white;
  border:none;border-radius:24px;font-size:.9rem;font-weight:600;
  cursor:pointer;letter-spacing:.04em;transition:opacity .2s;
}
.trans-start-btn:hover{opacity:.85}

/* Progress bar */
.trans-q-bar{
  height:4px;background:var(--ivory3);border-radius:2px;
  margin-bottom:1.2rem;overflow:hidden;
}
.trans-q-bar-fill{
  height:100%;background:var(--gold);border-radius:2px;
  transition:width .3s ease;
}
.trans-q-num{font-size:.7rem;color:var(--ink4);text-transform:uppercase;letter-spacing:.1em;margin-bottom:.6rem}
.trans-q-scenario{
  font-size:1rem;font-weight:600;color:var(--ink1);
  line-height:1.5;margin-bottom:1.4rem;
}
.trans-q-opts{display:flex;flex-direction:column;gap:.6rem;margin-bottom:1rem}
.trans-q-opt{
  display:flex;align-items:flex-start;gap:.8rem;
  padding:.8rem 1rem;
  background:var(--ivory2);border:1px solid var(--ivory3);
  border-radius:8px;cursor:pointer;text-align:left;
  font-size:.85rem;color:var(--ink2);line-height:1.5;
  transition:all .15s;
}
.trans-q-opt:hover{background:var(--gold-pale);border-color:var(--gold);color:var(--gold)}
.trans-q-letter{
  flex-shrink:0;width:22px;height:22px;
  background:var(--gold);color:white;
  font-size:.7rem;font-weight:700;
  display:flex;align-items:center;justify-content:center;
  border-radius:50%;margin-top:.05rem;
}
.trans-back-btn{
  background:none;border:1px solid var(--border);
  border-radius:6px;padding:.35rem .9rem;
  font-size:.75rem;color:var(--ink3);cursor:pointer;
}
.trans-q-nav{margin-top:.4rem}

/* Result */
.trans-res-header{
  background:var(--ivory2);border-radius:10px;
  padding:1.4rem 1.6rem;margin-bottom:1.2rem;
  text-align:center;
}
.trans-res-label{font-size:.7rem;text-transform:uppercase;letter-spacing:.1em;color:var(--ink4);margin-bottom:.3rem}
.trans-res-primary{font-size:2.5rem;font-weight:700;line-height:1.1;margin-bottom:.2rem;font-family:'Cormorant Garamond',serif}
.trans-res-name{font-size:1rem;font-weight:600;color:var(--ink1);margin-bottom:.4rem}
.trans-res-desc{font-size:.85rem;color:var(--ink3);font-style:italic}
.trans-res-bars{margin-bottom:1.2rem}
.trans-res-bar-row{display:flex;align-items:center;gap:.6rem;margin-bottom:.5rem}
.trans-res-bar-label{width:36px;font-size:.73rem;font-weight:700;flex-shrink:0;text-align:right}
.trans-res-bar-wrap{flex:1;height:10px;background:var(--ivory3);border-radius:5px;overflow:hidden}
.trans-res-bar-fill{height:100%;border-radius:5px;transition:width .6s ease}
.trans-res-bar-pct{width:36px;font-size:.72rem;color:var(--ink3)}
.trans-res-risk{
  background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.25);
  border-radius:8px;padding:1rem 1.2rem;margin-bottom:.8rem;
}
.trans-res-risk-title{font-size:.75rem;font-weight:700;color:#b91c1c;text-transform:uppercase;letter-spacing:.08em;margin-bottom:.4rem}
.trans-res-risk p{font-size:.82rem;color:var(--ink2);line-height:1.6;margin-bottom:.4rem}
.trans-res-risk-meta{font-size:.72rem;color:var(--ink3);font-style:italic}
.trans-res-fix{
  background:rgba(16,185,129,.08);border:1px solid rgba(16,185,129,.25);
  border-radius:8px;padding:1rem 1.2rem;margin-bottom:1.2rem;
}
.trans-res-fix-title{font-size:.75rem;font-weight:700;color:#059669;text-transform:uppercase;letter-spacing:.08em;margin-bottom:.4rem}
.trans-res-fix p{font-size:.82rem;color:var(--ink2);line-height:1.6}
.trans-res-actions{display:flex;gap:.8rem;justify-content:center;flex-wrap:wrap;margin-top:.5rem}
.trans-restart-btn{
  padding:.5rem 1.4rem;background:none;
  border:1px solid var(--border);border-radius:20px;
  font-size:.78rem;color:var(--ink3);cursor:pointer;
}

/* Footer external sites row */
.f-ext-sites{
  display:flex;flex-wrap:wrap;justify-content:center;gap:.4rem 1.2rem;
  padding:.6rem 1rem;border-bottom:1px solid rgba(255,255,255,.08);
  margin-bottom:.5rem;
}
.f-ext-link{
  font-size:.7rem;color:rgba(255,255,255,.55);text-decoration:none;
  transition:color .2s;
}
.f-ext-link:hover{color:var(--gold)}

/* ══ SOCIAL SHARING ══ */
.social-share-wrap{
  padding:1.2rem 0 .8rem;
  border-top:1px solid rgba(255,255,255,.1);
  margin-top:1rem;
}
.social-share-label{
  font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;
  color:rgba(255,255,255,.45);margin-bottom:.7rem;text-align:center;
}
.social-btns{
  display:flex;gap:.5rem;flex-wrap:wrap;justify-content:center;align-items:center;
}
.social-btn{
  display:inline-flex;align-items:center;gap:.4rem;
  padding:.4rem .85rem;border-radius:20px;border:none;cursor:pointer;
  font-size:.72rem;font-weight:600;line-height:1;text-decoration:none;
  transition:opacity .18s,transform .15s;white-space:nowrap;
}
.social-btn:hover{opacity:.85;transform:translateY(-1px)}
.social-btn-fb  {background:#1877f2;color:#fff}
.social-btn-tw  {background:#000;color:#fff}
.social-btn-li  {background:#0a66c2;color:#fff}
.social-btn-wa  {background:#25d366;color:#fff}
.social-btn-tg  {background:#229ed9;color:#fff}
.social-btn-copy{background:rgba(255,255,255,.12);color:rgba(255,255,255,.85);border:1px solid rgba(255,255,255,.2)}
.social-btn-copy.copied{background:rgba(46,125,79,.5);color:#fff}
.social-btn svg{width:14px;height:14px;flex-shrink:0}

/* Floating share button */
.share-fab{
  position:fixed;bottom:70px;right:14px;z-index:999;
  width:44px;height:44px;border-radius:50%;
  background:var(--gold);color:white;border:none;cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  font-size:1.1rem;box-shadow:0 3px 14px rgba(0,0,0,.25);
  transition:transform .2s,box-shadow .2s;
}
.share-fab:hover{transform:scale(1.08);box-shadow:0 5px 20px rgba(0,0,0,.3)}
.share-fab-panel{
  position:fixed;bottom:122px;right:14px;z-index:998;
  background:var(--slate, #2d3748);border-radius:12px;
  padding:.8rem .7rem;
  box-shadow:0 6px 28px rgba(0,0,0,.3);
  display:none;flex-direction:column;gap:.4rem;align-items:stretch;
  min-width:200px;
}
.share-fab-panel.open{display:flex}
.share-fab-panel-title{
  font-size:.65rem;letter-spacing:.1em;text-transform:uppercase;
  color:rgba(255,255,255,.5);text-align:center;margin-bottom:.2rem;
  padding-bottom:.4rem;border-bottom:1px solid rgba(255,255,255,.08);
}
.share-fab-btn{
  display:flex;align-items:center;gap:.6rem;
  padding:.5rem .7rem;border-radius:8px;border:none;cursor:pointer;
  font-size:.78rem;font-weight:600;color:white;text-decoration:none;
  transition:opacity .15s;
}
.share-fab-btn:hover{opacity:.85}
.share-fab-btn svg{width:16px;height:16px;flex-shrink:0}



