/* ══════════════════════════════════════
   MOBILE IMPROVEMENTS
   ══════════════════════════════════════ */

/* Hero: riduce padding su mobile */
@media(max-width:600px){
  #hero{padding:5.5rem 1.2rem 4rem}
  h1.hero-title{font-size:clamp(2.4rem,9vw,3.2rem);margin-bottom:1rem}
  .hero-sub{font-size:.92rem;margin-bottom:1.8rem;padding:.4rem .9rem}
  .hero-pills{gap:.4rem;margin-bottom:2rem}
  .pill{font-size:.72rem;padding:.35rem .85rem}
  .cta-row{gap:.7rem}
  .btn-gold,.btn-ghost{font-size:.8rem;padding:.65rem 1.4rem}
  .hero-eyebrow{font-size:.72rem;margin-bottom:1.2rem}
  .scroll-hint{display:none}
}

/* Chi sono: rimuove sticky su mobile */
@media(max-width:760px){
  .chisono-card{position:static;margin-bottom:2rem}
  .chisono-avatar{max-width:200px;margin:0 auto}
}

/* Footer: migliora su schermi molto piccoli */
@media(max-width:380px){
  .footer-grid{grid-template-columns:1fr !important;padding:0 1rem 2rem}
  .f-ext-sites{display:flex;flex-direction:column;gap:.4rem}
  .f-ext-link{font-size:.73rem}
}

/* Mob menu: migliora scrollabilità */
@media(max-width:768px){
  #mob-menu{max-height:75vh;overflow-y:auto;-webkit-overflow-scrolling:touch}
  .mob-link{font-size:.83rem;padding:.65rem .9rem}
}

/* Sezioni generali: meno padding su mobile */
@media(max-width:480px){
  section{padding:3rem 0}
  .container{padding:0 1rem}
  .sec-title{font-size:1.6rem}
  h2.sec-title{font-size:clamp(1.5rem,5vw,2rem)}
}

/* Viaggio timeline: scroll orizzontale su mobile */
@media(max-width:700px){
  .viaggio-timeline{
    display:flex;flex-direction:column;
    align-items:stretch;gap:.8rem
  }
  .viaggio-arrow{transform:rotate(90deg);text-align:center;font-size:1.5rem;color:var(--ink4)}
  .viaggio-fase{flex-direction:row;align-items:center;gap:1rem;text-align:left}
  .viaggio-fase-num{flex-shrink:0}
  .viaggio-fase-tools{display:flex;flex-wrap:wrap;gap:.3rem;margin-top:.3rem}
}



