/* ══ NAV DROPDOWN ══ */
.nav-dropdown{position:relative;display:inline-block}
.nav-dd-trigger{display:flex;align-items:center;gap:.3rem}
.nav-dd-arrow{font-size:.65rem;transition:transform .2s;display:inline-block}
.nav-dropdown.open .nav-dd-arrow{transform:rotate(180deg)}
.nav-dd-menu{display:none;position:absolute;top:calc(100% + 6px);right:0;min-width:180px;background:var(--ivory);border:1px solid var(--border2);border-radius:var(--r);box-shadow:var(--shadow2);z-index:9999;padding:.4rem 0;animation:ddFadeIn .15s ease}
@keyframes ddFadeIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}
.nav-dropdown.open .nav-dd-menu{display:block}
.nav-dd-item{display:block;width:100%;padding:.55rem 1rem;background:transparent;border:none;cursor:pointer;font-family:inherit;font-size:.8rem;font-weight:400;letter-spacing:.06em;text-transform:uppercase;color:var(--ink2);text-align:left;transition:background .15s,color .15s}
.nav-dd-item:hover{background:rgba(184,147,90,.08);color:var(--gold)}
.nav-dd-sep{border:none;border-top:1px solid var(--border);margin:.3rem .7rem}
