#admin-overlay{display:none;position:fixed;inset:0;background:rgba(42,37,32,.72);z-index:99999;backdrop-filter:blur(4px);align-items:center;justify-content:center}
#admin-overlay.open{display:flex}
#admin-panel{background:var(--ivory);border-radius:var(--rl);width:min(92vw,820px);max-height:88vh;overflow-y:auto;box-shadow:0 24px 80px rgba(42,37,32,.28);animation:ddFadeIn .2s ease}
.adm-hd{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.8rem;border-bottom:1px solid var(--border);position:sticky;top:0;background:var(--ivory);z-index:1}
.adm-title{font-family:'Cormorant Garamond',serif;font-size:1.4rem;font-weight:600;color:var(--ink)}
.adm-close{background:transparent;border:none;cursor:pointer;font-size:1.3rem;color:var(--ink3);padding:.2rem .5rem;border-radius:4px;transition:color .2s}
