.adm-pwd-wrap{display:flex;gap:.6rem;max-width:320px;margin:0 auto}
.adm-pwd{flex:1;padding:.65rem 1rem;border:1px solid var(--border2);border-radius:var(--r);font-family:inherit;font-size:.9rem;background:#fff;color:var(--ink);outline:none}
.adm-pwd:focus{border-color:var(--gold)}
.adm-btn{padding:.65rem 1.2rem;background:var(--gold);color:#fff;border:none;border-radius:var(--r);cursor:pointer;font-family:inherit;font-size:.85rem;font-weight:600;transition:background .2s}
.adm-btn:hover{background:var(--gold2)}
.adm-body{padding:1.5rem 1.8rem;display:none}
.adm-body.visible{display:block}
.adm-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;margin-bottom:1.8rem}
