#mob-menu{max-height:calc(100vh - 68px);overflow-y:auto}

/* ══ PERCORSO TRACKER ══ */
#percorso-banner{position:fixed;bottom:18px;right:18px;z-index:201;width:min(380px,calc(100vw - 40px));background:white;border:1px solid var(--border2);border-left:4px solid var(--gold);border-radius:14px;box-shadow:0 14px 40px rgba(42,37,32,.22);padding:1.1rem 1.2rem}
.pb-inner{display:flex;flex-direction:column;gap:.7rem}
.pb-header{display:flex;align-items:center;gap:.7rem;position:relative}
.pb-icon{font-size:1.5rem}
.pb-title-wrap{flex:1;min-width:0}
.pb-eyebrow{font-size:.62rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--gold)}
.pb-title{font-family:'Cormorant Garamond',serif;font-size:1.1rem;font-weight:600;color:var(--ink);line-height:1.2;margin-top:2px}
.pb-close{position:absolute;top:-.4rem;right:-.6rem;width:24px;height:24px;border-radius:50%;background:var(--ivory);border:1px solid var(--border);cursor:pointer;color:var(--ink3);font-size:.7rem;font-weight:700;display:flex;align-items:center;justify-content:center}
.pb-progress{display:flex;flex-direction:column;gap:.5rem}
.pb-progress-bar{height:4px;background:var(--ivory2);border-radius:2px;overflow:hidden}
.pb-progress-fill{height:100%;background:linear-gradient(90deg,var(--gold2),var(--gold));transition:width .6s ease}
.pb-steps{display:flex;flex-direction:column;gap:.25rem;font-size:.75rem;color:var(--ink3)}
.pb-step{display:flex;align-items:center;gap:.5rem;padding:.25rem 0;cursor:pointer}
.pb-step.pb-done{color:#3d5a48}
.pb-step.pb-done::before{content:'✓';color:#3d5a48;font-weight:700;width:16px}
.pb-step.pb-active{color:var(--gold);font-weight:600}
.pb-step.pb-active::before{content:'▸';color:var(--gold);width:16px}
.pb-step.pb-todo::before{content:'○';color:var(--ink4);width:16px}
.pb-cta{display:flex;gap:.4rem;flex-wrap:wrap}
.pb-cta-btn{flex:1;padding:.55rem .9rem;background:var(--gold);color:white;border:none;border-radius:8px;cursor:pointer;font-family:inherit;font-size:.78rem;font-weight:600}
.pb-cta-btn:hover{background:var(--gold2)}
body.has-percorso #progress-widget{bottom:auto;top:90px}

/* ══ LEGGI DI PIÙ ══ */
.intro-collapsible{position:relative;max-height:200px;overflow:hidden;transition:max-height .4s ease}
.intro-collapsible::after{content:'';position:absolute;bottom:0;left:0;right:0;height:60px;background:linear-gradient(180deg,transparent,white 80%);pointer-events:none}
.intro-collapsible.expanded{max-height:none}
.intro-collapsible.expanded::after{opacity:0}
.intro-toggle{display:inline-block;margin-top:.6rem;background:transparent;border:none;color:var(--gold);font-family:inherit;font-size:.78rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;cursor:pointer;padding:.3rem 0}

/* ══ CHAT MESSAGES IMPROVED ══ */
.chat-messages{min-height:420px;max-height:680px;overflow-y:auto;scroll-behavior:smooth}
.chat-messages::-webkit-scrollbar{width:8px}
.chat-messages::-webkit-scrollbar-track{background:var(--ivory2)}
.chat-messages::-webkit-scrollbar-thumb{background:var(--gold);border-radius:4px}
.msg-bubble.ai{max-width:82%;word-wrap:break-word;overflow-wrap:break-word}
.msg-bubble.ai .ai-table-wrap{max-width:calc(100vw - 120px);overflow-x:auto;margin:1rem 0}
.msg-bubble.ai:has(.ai-table-wrap){max-width:92%}
.msg-bubble.ai p{margin:.5rem 0}
.msg-bubble.ai h3,.msg-bubble.ai h4{font-family:'Cormorant Garamond',serif;font-size:1.05rem;font-weight:600;color:var(--gold);margin:.8rem 0 .4rem}
.msg-bubble.ai ul,.msg-bubble.ai ol{padding-left:1.4rem;margin:.5rem 0}
.msg-bubble.ai li{margin:.25rem 0}

/* ══ VIAGGIO COMPACT ══ */
.viaggio-compact-sec{
  padding:3.5rem 0 4rem;
  background:linear-gradient(180deg, var(--ivory) 0%, #fff 100%);
  border-top:1px solid var(--border)
}
.viaggio-compact-head{text-align:center;margin-bottom:2rem;max-width:720px;margin-left:auto;margin-right:auto;padding:0 1.5rem}
.viaggio-compact-eye{font-size:.68rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);margin-bottom:.6rem}
.viaggio-compact-title{font-family:'Cormorant Garamond',serif;font-size:clamp(1.6rem,3vw,2.2rem);font-weight:600;color:var(--ink);line-height:1.15;margin:0 0 .8rem}
.viaggio-compact-title em{font-style:italic;color:var(--gold)}
.viaggio-compact-desc{font-size:.88rem;color:var(--ink3);line-height:1.6;margin:0}
.viaggio-link-btn{background:transparent;border:none;cursor:pointer;color:var(--gold);font-family:inherit;font-size:inherit;font-weight:600;padding:0;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
.viaggio-link-btn:hover{color:var(--gold2)}
.viaggio-compact-timeline{
  display:flex;align-items:stretch;gap:.5rem;justify-content:center;flex-wrap:wrap;
  max-width:1200px;margin:0 auto;padding:0 1.5rem
}
.vc-fase{
  flex:1;min-width:160px;max-width:220px;
  background:white;border:1px solid var(--border2);border-radius:10px;
  padding:.9rem .8rem;text-align:center;cursor:pointer;
  transition:transform .2s,box-shadow .2s,border-color .2s;position:relative
}
.vc-fase::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;border-radius:10px 10px 0 0}
.vc-f0::before{background:#b8935a}
.vc-f1::before{background:#2e7d4f}
.vc-f2::before{background:#3a4a5a}
.vc-f3::before{background:#7b2fa0}
.vc-f4::before{background:#1565c0}
.vc-fase:hover{transform:translateY(-3px);box-shadow:0 6px 20px rgba(42,37,32,.1);border-color:var(--gold)}
.vc-num{font-family:'Cormorant Garamond',serif;font-size:1.5rem;font-weight:700;color:var(--gold);line-height:1}
.vc-title{font-family:'Cormorant Garamond',serif;font-size:1rem;font-weight:600;color:var(--ink);margin:.35rem 0 .2rem;line-height:1.2}
.vc-meta{font-size:.68rem;color:var(--ink3);line-height:1.4}
.vc-arrow{display:flex;align-items:center;font-size:1.4rem;color:var(--gold);font-weight:300}
@media (max-width:900px){
  .viaggio-compact-timeline{flex-direction:column;align-items:stretch}
  .vc-fase{max-width:none}
  .vc-arrow{display:none}
}


/* ══ HOME DASHBOARD RESPONSIVE FIX (aggiunto) ══ */

/* Links styled as buttons should NOT have underline */
a.btn-gold, a.btn-ghost, a.qs-btn, a.dash-card, a.mega-item, a.mob-link, a.f-link, a.vc-fase, a.nav-link, a.hdr-brand {
  text-decoration: none !important;
}

/* Ensure button-styled links display block-level properly */
a.btn-gold, a.btn-ghost {
  display: inline-block;
  text-align: center;
  text-decoration: none !important;
}

/* Desktop: default state */
.hamburger { display: none; }
.mega-menu-wrap { display: inline-block; }

/* Mobile (< 768px): hamburger shown, mega menu hidden, other nav items hidden */
@media (max-width: 768px) {
  .hamburger { display: flex !important; }
  .mega-menu-wrap { display: none !important; }
  .nav-phase { display: none !important; }
  .search-btn { display: none !important; }

  /* Header: ensure inner layout is clean on mobile */
  .hdr-inner {
    padding: 0 1rem !important;
  }
  .hdr-title {
    font-size: 1.1rem !important;
  }

  /* Hero CTAs: stack vertically on mobile */
  .hero-ctas {
    flex-direction: column !important;
    gap: 0.8rem !important;
    align-items: stretch !important;
  }
  .hero-ctas a.btn-gold,
  .hero-ctas a.btn-ghost {
    width: 100% !important;
    padding: 0.95rem 1.5rem !important;
    font-size: 0.82rem !important;
    display: block !important;
  }
}

/* Mobile menu should only be shown when toggled open, not always */
#mob-menu {
  display: none;
  position: fixed;
  top: 68px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--ivory);
  z-index: 9999;
  padding: 1rem 1.5rem 2rem;
  overflow-y: auto;
}
#mob-menu.open {
  display: block;
}
body.mob-open {
  overflow: hidden;
}

/* Mobile menu links */
#mob-menu .mob-link {
  display: block;
  width: 100%;
  padding: 0.7rem 1rem;
  background: transparent;
  border: none;
  border-bottom: 1px solid var(--border);
  text-align: left;
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--ink2);
  cursor: pointer;
  text-decoration: none !important;
}
#mob-menu .mob-link:hover {
  background: rgba(184,147,90,0.08);
  color: var(--gold);
}

/* Hamburger icon styling */
.hamburger {
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--ink);
  background: transparent;
  border: none;
  padding: 0.4rem 0.6rem;
  line-height: 1;
}

/* CTA buttons full visibility */
.hero-ctas {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  margin-top: 1.5rem;
}


/* ═════════ FIX CRITICI v2 — HERO Z-INDEX + HEADER UX ═════════ */

/* HERO: assicura che il contenuto sia SOPRA l'overlay e i circles */
#hero {
  position: relative !important;
}
.hero-overlay {
  z-index: 1 !important;
  pointer-events: none !important;  /* CRITICO: l'overlay non blocca i click */
}
.hero-bg-circle {
  z-index: 0 !important;
  pointer-events: none !important;
}
.hero-container {
  position: relative !important;
  z-index: 10 !important;  /* SOPRA tutto */
}
.hero-ctas {
  position: relative !important;
  z-index: 10 !important;
}
.hero-ctas a.btn-gold,
.hero-ctas a.btn-ghost {
  position: relative !important;
  z-index: 11 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
}

/* CTAs migliorate: contrasto e leggibilità */
.hero-ctas a.btn-gold {
  background: var(--gold) !important;
  color: white !important;
  border: 2px solid var(--gold) !important;
  font-weight: 600 !important;
  letter-spacing: 0.08em !important;
  text-transform: uppercase !important;
  padding: 0.95rem 2rem !important;
  font-size: 0.85rem !important;
  border-radius: 8px !important;
  box-shadow: 0 6px 20px rgba(184,147,90,0.35) !important;
  transition: all 0.2s ease !important;
}
.hero-ctas a.btn-gold:hover {
  background: #a07840 !important;
  border-color: #a07840 !important;
  transform: translateY(-2px) !important;
  box-shadow: 0 10px 28px rgba(184,147,90,0.5) !important;
}

.hero-ctas a.btn-ghost {
  background: rgba(255,255,255,0.95) !important;
  color: var(--ink) !important;
  border: 2px solid white !important;
  font-weight: 600 !important;
  letter-spacing: 0.08em !important;
  text-transform: uppercase !important;
  padding: 0.95rem 2rem !important;
  font-size: 0.85rem !important;
  border-radius: 8px !important;
  text-shadow: none !important;
  box-shadow: 0 6px 20px rgba(0,0,0,0.2) !important;
  transition: all 0.2s ease !important;
}
.hero-ctas a.btn-ghost:hover {
  background: white !important;
  color: var(--gold) !important;
  border-color: var(--gold) !important;
  transform: translateY(-2px) !important;
  box-shadow: 0 10px 28px rgba(0,0,0,0.25) !important;
}

/* HEADER più pulito */
#hdr {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(249,245,239,0.96);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  padding: 0.85rem 0;
}
.hdr-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.hdr-brand {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-family: 'Cormorant Garamond', serif;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--ink);
  text-decoration: none;
}
.hdr-logo {
  font-size: 1.4rem;
  color: var(--gold);
}
nav {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}
.search-btn {
  background: transparent;
  border: 1px solid var(--border2);
  color: var(--ink2);
  width: 38px;
  height: 38px;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.search-btn:hover {
  background: var(--gold);
  color: white;
  border-color: var(--gold);
}
@media (max-width: 768px) {
  .search-btn { display: none !important; }
}

/* Mobile fixes */
@media (max-width: 768px) {
  .hdr-inner { padding: 0 1rem; }
  .hdr-title { font-size: 1.05rem; }
  .hero-ctas {
    flex-direction: column !important;
    gap: 0.7rem !important;
    align-items: stretch !important;
  }
  .hero-ctas a.btn-gold,
  .hero-ctas a.btn-ghost {
    width: 100% !important;
    padding: 1rem 1.5rem !important;
    font-size: 0.78rem !important;
  }
}


/* ═══ FIX HERO EYEBROW — perfetta centratura ═══ */
.hero-eyebrow {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 1rem !important;
  margin-left: auto !important;
  margin-right: auto !important;
  text-align: center !important;
  white-space: nowrap !important;
  width: fit-content !important;
  max-width: 100% !important;
}
.hero-eyebrow::before,
.hero-eyebrow::after {
  content: '' !important;
  display: block !important;
  width: 50px !important;
  height: 1px !important;
  background: var(--gold3) !important;
  flex-shrink: 0 !important;
}
@media (max-width: 600px) {
  .hero-eyebrow {
    white-space: normal !important;
    font-size: 0.65rem !important;
    letter-spacing: 0.25em !important;
  }
  .hero-eyebrow::before,
  .hero-eyebrow::after {
    width: 25px !important;
  }
}

/* Hero container deve essere centrato */
.hero-container {
  text-align: center !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
}


/* ════════════════════════════════════════════════════════════ */
/* ═══ FIX MEGA-MENU LEGGIBILITÀ — override completo  ═══════ */
/* ════════════════════════════════════════════════════════════ */

/* PANEL: più contrasto, più spazio interno */
.mega-panel {
  background: #ffffff !important;
  border: 1px solid rgba(184,147,90,.35) !important;
  padding: 2rem 1.8rem !important;
  gap: 1.6rem !important;
  box-shadow: 0 24px 80px rgba(42,37,32,.28) !important;
  grid-template-columns: repeat(5, 1fr) !important;
}

/* Su schermi medi: 4 colonne */
@media (max-width: 1100px) {
  .mega-panel {
    grid-template-columns: repeat(4, 1fr) !important;
    width: min(96vw, 1080px) !important;
  }
}

/* Su schermi piccoli: 3 colonne */
@media (max-width: 850px) {
  .mega-panel {
    grid-template-columns: repeat(3, 1fr) !important;
    width: min(96vw, 880px) !important;
  }
}

/* Su mobile: 2 colonne */
@media (max-width: 600px) {
  .mega-panel {
    grid-template-columns: repeat(2, 1fr) !important;
    width: 96vw !important;
    padding: 1.5rem 1.2rem !important;
    gap: 1.2rem !important;
  }
}

/* TITOLO COLONNA: più grande, più scuro */
.mega-col-title {
  font-size: 0.78rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.1em !important;
  color: #8a6a3a !important;
  padding: 0 0.5rem 0.6rem !important;
  border-bottom: 1.5px solid rgba(184,147,90,.3) !important;
  margin-bottom: 0.7rem !important;
}

/* COLONNA: più gap tra item */
.mega-col {
  gap: 0.4rem !important;
}

/* ITEM: padding generoso, hover evidente */
.mega-item {
  display: flex !important;
  align-items: flex-start !important;
  gap: 0.7rem !important;
  padding: 0.7rem 0.8rem !important;
  border-radius: 8px !important;
  transition: background 0.15s, transform 0.15s !important;
  text-decoration: none !important;
}
.mega-item:hover {
  background: rgba(184,147,90,.12) !important;
  transform: translateX(3px) !important;
}

/* ICONA: più grande, evidente */
.mi-ic {
  font-size: 1.35rem !important;
  line-height: 1.2 !important;
  flex-shrink: 0 !important;
  width: 26px !important;
  text-align: center !important;
  color: #b8935a !important;
}

/* CORPO TESTO: line-height + spaziatura */
.mi-body {
  display: flex !important;
  flex-direction: column !important;
  gap: 3px !important;
  line-height: 1.4 !important;
  min-width: 0 !important;
}

/* TITOLO ITEM (strong): font grande, contrasto massimo */
.mi-body strong {
  font-size: 0.98rem !important;
  font-weight: 600 !important;
  color: #2a2520 !important;
  letter-spacing: 0 !important;
  line-height: 1.3 !important;
}

/* SOTTOTITOLO ITEM (em): contrasto migliorato (era #7a7268, ora #5a5450) */
.mi-body em {
  font-size: 0.83rem !important;
  font-style: normal !important;
  color: #4a4540 !important;
  letter-spacing: 0 !important;
  line-height: 1.4 !important;
}

/* ITEM STAR (in evidenza): bordo dorato più visibile */
.mega-item-star {
  background: linear-gradient(135deg, rgba(184,147,90,.14), rgba(184,147,90,.04)) !important;
  border: 1.5px solid rgba(184,147,90,.35) !important;
  padding: 0.85rem 0.85rem !important;
  margin-bottom: 0.4rem !important;
}
.mega-item-star:hover {
  background: linear-gradient(135deg, rgba(184,147,90,.22), rgba(184,147,90,.08)) !important;
  border-color: rgba(184,147,90,.55) !important;
}

/* ITEM SMALL: comunque leggibile */
.mega-item-small {
  padding: 0.55rem 0.8rem !important;
  font-size: 0.8rem !important;
}
.mega-item-small .mi-body strong {
  font-size: 0.84rem !important;
}
.mega-item-small .mi-body em {
  font-size: 0.74rem !important;
}

/* AI items conservano i loro colori specifici */
.mega-item-ai-fes .mi-ic { color: #8b78e6 !important; }
.mega-item-ai-bush .mi-ic { color: #c8813a !important; }

/* BACKDROP: rimuovi BLUR (rovinava la leggibilità), scurisci tantissimo */
.mega-backdrop {
  background: rgba(20,15,10,.78) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* PANEL: rinforza ulteriormente lo stacco visivo */
.mega-panel {
  background: #ffffff !important;
  border: 2px solid #b8935a !important;
  box-shadow: 0 30px 100px rgba(0,0,0,.35), 0 0 0 1px rgba(184,147,90,.2) !important;
}

/* Forza opacità 100% del menu (combatte qualsiasi animation) */
.mega-panel,
.mega-panel * {
  opacity: 1 !important;
}

/* Annulla qualsiasi filter o backdrop-filter sul menu */
.mega-panel,
.mega-panel *,
.mega-col,
.mega-item,
.mi-body,
.mi-body strong,
.mi-body em,
.mi-ic {
  filter: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ══ MOBILE READABILITY & TOUCH TARGETS ══ */
/* Micro-label e chip diventano leggibili su schermi piccoli (WCAG: testo body min 12px). */
@media (max-width: 640px) {
  .perc-chip { font-size: 0.78rem; padding: 0.28rem 0.65rem; }
  .percorso-tag { font-size: 0.8rem; padding: 0.22rem 0.7rem; }
  .perc-cta { font-size: 0.82rem; }
  .ps-new { font-size: 0.88rem; padding: 0.5rem 0; }
}

/* Garantisce area tappabile minima 44x44px (Apple HIG) per i link "brand" e bottoni icona */
.hdr-brand { min-height: 44px; }
.hdr-brand .hdr-logo { line-height: 1; }

/* iPad (portrait/landscape): layout più arioso per la quick-start bar */
@media (min-width: 769px) and (max-width: 1024px) {
  .qs-inner { gap: 0.7rem; padding: 0 1.2rem; }
  .qs-label { font-size: 0.88rem; }
  .qs-btn { min-width: 0; padding: 0.55rem 0.8rem; }
  .qs-buttons { gap: 0.5rem; }
}

olismo-portale.css:
/*!
 * olismo-portale.css — Stile condiviso delle pagine
 * © 2016-2026 Avv. Carlo Alberto Calcagno · olismo-integrato.it
 * Palette coerente con olismo-core.js e con il manuale
 * "Leggere la persona, accompagnare il conflitto"
 */

/* ═══ VARIABILI PALETTE ═══ */
:root {
  /* Oro e avorio — identità principale del manuale */
  --gold: #c9a227;
  --gold-dark: #8a6a14;
  --gold-soft: #e8d08a;
  --ivory: #fcfaf4;
  --ivory-2: #f5efe0;
  --ivory-3: #ede3c8;

  /* Inchiostro — per i testi */
  --ink: #2a2520;
  --ink-2: #4a4540;
  --ink-3: #6a6560;
  --ink-light: #8a8580;

  /* Palette chakra — dal core JS */
  --ck-1: #a83232; /* rosso radice */
  --ck-2: #c45a22; /* arancio sacrale */
  --ck-3: #c49a1a; /* giallo plesso */
  --ck-4: #2e7d4f; /* verde cuore */
  --ck-5: #1565c0; /* blu gola */
  --ck-6: #4527a0; /* indaco */
  --ck-7: #7b2fa0; /* viola corona */

  /* Semaforo allerta */
  --alert-red: #c62828;
  --alert-red-bg: #fdecea;
  --alert-amber: #e6a817;
  --alert-amber-bg: #fdf7e4;
  --safe-green: #2e7d4f;
  --safe-green-bg: #e7f3ec;

  /* Tipografia */
  --font-title: "EB Garamond", Garamond, "Times New Roman", serif;
  --font-body: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue",
               Arial, sans-serif;
}

/* ═══ RESET & BASE ═══ */
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  padding: 0;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  color: var(--ink);
  background: var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ═══ LAYOUT BASE ═══ */
.container {
  max-width: 820px;
  margin: 0 auto;
  padding: 0 24px;
}
.container-wide {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ═══ HEADER DI PAGINA ═══ */
.site-header {
  background: linear-gradient(180deg, var(--ivory-2) 0%, var(--ivory) 100%);
  border-bottom: 2px solid var(--gold);
  padding: 28px 0 22px;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(138, 106, 20, 0.06);
}
.site-header__inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}
.site-logo {
  font-family: var(--font-title);
  font-size: 22px;
  font-weight: 600;
  color: var(--gold-dark);
  text-decoration: none;
  letter-spacing: 0.4px;
}
.site-logo span {
  color: var(--ink-2);
  font-weight: 400;
  font-size: 14px;
  display: block;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-top: 2px;
}

.site-nav {
  display: flex;
  gap: 22px;
  flex-wrap: wrap;
}
.site-nav a {
  color: var(--ink-2);
  text-decoration: none;
  font-size: 15px;
  font-weight: 500;
  padding: 6px 0;
  border-bottom: 2px solid transparent;
  transition: color .2s, border-color .2s;
}
.site-nav a:hover {
  color: var(--gold-dark);
  border-bottom-color: var(--gold);
}
.site-nav a.active {
  color: var(--gold-dark);
  border-bottom-color: var(--gold);
}

/* ═══ HERO DI PAGINA ═══ */
.page-hero {
  padding: 60px 0 40px;
  text-align: center;
  border-bottom: 1px solid var(--ivory-3);
  margin-bottom: 48px;
}
.page-hero__eyebrow {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--gold-dark);
  margin-bottom: 14px;
}
.page-hero__title {
  font-family: var(--font-title);
  font-size: 48px;
  font-weight: 500;
  line-height: 1.15;
  color: var(--ink);
  margin: 0 0 18px;
  letter-spacing: -0.5px;
}
.page-hero__subtitle {
  font-family: var(--font-title);
  font-size: 22px;
  font-style: italic;
  color: var(--ink-2);
  max-width: 640px;
  margin: 0 auto;
  line-height: 1.45;
}
@media (max-width: 700px) {
  .page-hero__title { font-size: 34px; }
  .page-hero__subtitle { font-size: 18px; }
  .page-hero { padding: 40px 0 28px; }
}

/* ═══ TIPOGRAFIA PAGINA ═══ */
h2 {
  font-family: var(--font-title);
  font-size: 32px;
  font-weight: 500;
  color: var(--gold-dark);
  margin: 56px 0 20px;
  line-height: 1.25;
  letter-spacing: -0.3px;
}
h2::before {
  content: "§";
  color: var(--gold);
  margin-right: 12px;
  font-size: 26px;
  font-weight: 400;
  position: relative;
  top: -3px;
}
h3 {
  font-family: var(--font-title);
  font-size: 23px;
  font-weight: 500;
  font-style: italic;
  color: var(--gold-dark);
  margin: 36px 0 12px;
}
h4 {
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
  margin: 24px 0 8px;
  letter-spacing: 0.3px;
}

p {
  margin: 0 0 16px;
}
p.lead {
  font-family: var(--font-title);
  font-size: 21px;
  font-style: italic;
  color: var(--ink-2);
  line-height: 1.55;
  margin-bottom: 28px;
}

a { color: var(--gold-dark); text-decoration: underline; text-underline-offset: 3px; }
a:hover { color: var(--ck-1); }

ul, ol {
  margin: 0 0 18px;
  padding-left: 24px;
}
li { margin-bottom: 8px; }

strong { color: var(--ink); font-weight: 700; }
em { color: var(--ink-2); }

blockquote {
  border-left: 3px solid var(--gold);
  margin: 24px 0;
  padding: 8px 20px;
  color: var(--ink-2);
  font-style: italic;
  font-family: var(--font-title);
  font-size: 19px;
  background: var(--ivory-2);
}

/* ═══ BOX COMPONENTI (coerenti con il manuale) ═══ */
.box-gold {
  background: linear-gradient(180deg, #fdf6dc 0%, #f8ecb8 100%);
  border-left: 4px solid var(--gold);
  padding: 22px 26px;
  margin: 28px 0;
  border-radius: 2px;
  box-shadow: 0 1px 4px rgba(138, 106, 20, 0.08);
}
.box-gold__title {
  font-family: var(--font-title);
  font-size: 20px;
  font-weight: 600;
  color: var(--gold-dark);
  margin: 0 0 10px;
  font-style: italic;
}
.box-gold p { margin-bottom: 10px; }
.box-gold p:last-child { margin-bottom: 0; }

.box-blue {
  background: #eff3f8;
  border-left: 4px solid var(--ck-5);
  padding: 22px 26px;
  margin: 28px 0;
  border-radius: 2px;
}
.box-blue__title {
  font-family: var(--font-title);
  font-size: 20px;
  font-weight: 600;
  color: var(--ck-5);
  margin: 0 0 10px;
  font-style: italic;
}

.box-alert {
  background: var(--alert-red-bg);
  border: 2px solid var(--alert-red);
  padding: 22px 26px;
  margin: 28px 0;
  border-radius: 4px;
}
.box-alert__title {
  font-size: 17px;
  font-weight: 700;
  color: var(--alert-red);
  margin: 0 0 10px;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 10px;
}
.box-alert__title::before {
  content: "⚠";
  font-size: 22px;
}
.box-alert p { color: #6a1e1e; }
.box-alert strong { color: var(--alert-red); }

.box-care {
  background: var(--safe-green-bg);
  border-left: 4px solid var(--safe-green);
  padding: 22px 26px;
  margin: 28px 0;
  border-radius: 2px;
}
.box-care__title {
  font-family: var(--font-title);
  font-size: 20px;
  font-weight: 600;
  color: var(--safe-green);
  margin: 0 0 10px;
  font-style: italic;
}

/* ═══ CARDS ═══ */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 22px;
  margin: 32px 0;
}
.card {
  background: #fff;
  border: 1px solid var(--ivory-3);
  border-radius: 6px;
  padding: 22px 24px;
  transition: transform .2s, box-shadow .2s, border-color .2s;
}
.card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 24px rgba(138, 106, 20, 0.1);
  border-color: var(--gold-soft);
}
.card__number {
  font-family: var(--font-title);
  font-size: 42px;
  font-weight: 600;
  color: var(--gold);
  line-height: 1;
  margin-bottom: 8px;
}
.card__title {
  font-family: var(--font-title);
  font-size: 20px;
  font-weight: 600;
  color: var(--ink);
  margin: 0 0 10px;
}
.card__title em {
  display: block;
  font-size: 14px;
  color: var(--ink-3);
  font-weight: 400;
  margin-top: 4px;
}
.card__body {
  font-size: 15px;
  color: var(--ink-2);
  line-height: 1.55;
}
.card a.card__link {
  display: inline-block;
  margin-top: 12px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  color: var(--gold-dark);
}
.card a.card__link::after { content: " →"; }

/* Card variante enneatipi, colorata */
.card-ennea {
  position: relative;
  overflow: hidden;
}
.card-ennea::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 6px;
  background: var(--accent, var(--gold));
}
.card-ennea .card__title { padding-left: 6px; }

/* ═══ TABELLE ═══ */
.table {
  width: 100%;
  border-collapse: collapse;
  margin: 28px 0;
  font-size: 15px;
}
.table th {
  background: var(--ivory-2);
  color: var(--gold-dark);
  padding: 12px 14px;
  text-align: left;
  font-family: var(--font-title);
  font-weight: 600;
  font-size: 16px;
  border-bottom: 2px solid var(--gold);
}
.table td {
  padding: 11px 14px;
  border-bottom: 1px solid var(--ivory-3);
  vertical-align: top;
}
.table tr:nth-child(even) td { background: #fbf9f2; }
.table tr:last-child td { border-bottom: none; }

/* ═══ CTA ═══ */
.cta-button {
  display: inline-block;
  padding: 14px 32px;
  background: var(--gold-dark);
  color: var(--ivory);
  text-decoration: none;
  border-radius: 3px;
  font-weight: 600;
  letter-spacing: 0.3px;
  transition: background .2s;
  font-size: 16px;
}
.cta-button:hover {
  background: var(--ink);
  color: var(--ivory);
}
.cta-button--outline {
  background: transparent;
  color: var(--gold-dark);
  border: 2px solid var(--gold-dark);
  padding: 12px 30px;
}
.cta-button--outline:hover {
  background: var(--gold-dark);
  color: var(--ivory);
}

/* ═══ SEPARATORE ORNAMENTALE ═══ */
.ornament {
  text-align: center;
  margin: 48px 0;
  color: var(--gold);
  font-size: 22px;
  letter-spacing: 20px;
}
.ornament::before { content: "✦ ✦ ✦"; }

/* ═══ FOOTER ═══ */
.site-footer {
  background: var(--ink);
  color: var(--ivory-3);
  padding: 48px 0 28px;
  margin-top: 80px;
  font-size: 14px;
}
.site-footer__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 32px;
  margin-bottom: 32px;
}
.site-footer h5 {
  color: var(--gold-soft);
  font-family: var(--font-title);
  font-size: 17px;
  margin: 0 0 12px;
  font-weight: 600;
}
.site-footer a {
  color: var(--ivory-3);
  text-decoration: none;
  display: block;
  padding: 3px 0;
  font-size: 14px;
}
.site-footer a:hover { color: var(--gold-soft); }
.site-footer__legal {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 20px;
  font-size: 12px;
  color: var(--ink-light);
  line-height: 1.6;
}
.site-footer__legal p { margin: 0 0 8px; }

/* ═══ ACCESSIBILITÀ & PRINT ═══ */
a:focus-visible, button:focus-visible {
  outline: 3px solid var(--gold);
  outline-offset: 2px;
}
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}
@media print {
  .site-header, .site-footer, .site-nav { display: none; }
  body { background: white; color: black; }
  .box-gold, .box-blue, .box-alert, .box-care { break-inside: avoid; }
}

/* ═══ RIFERIMENTO A VIOLENZA (banner emergenza) ═══ */
.emergency-banner {
  background: var(--alert-red);
  color: white;
  text-align: center;
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 500;
}
.emergency-banner a {
  color: white;
  text-decoration: underline;
  font-weight: 700;
}
.emergency-banner strong { color: white; }
